tool_schemas.implementation:
def firecrawl_scrape(url, formats=None, onlyMainContent=None, includeHtml=None, includeMarkdown=None, includeText=None, waitFor=None, timeout=None, headers=None, cookies=None, proxy=None, webhook=None, webhookSecret=None, priority=None, **_extra):
    import json, os, datetime, time, re, hashlib, urllib.parse

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0122000" if __import__("os").path.isdir("./environment_mix/0122000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _month():
        return datetime.datetime.utcnow().strftime("%Y-%m")

    def _is_abs_http_url(u):
        if not isinstance(u, str) or not u:
            return False
        try:
            p = urllib.parse.urlparse(u)
        except Exception:
            return False
        return p.scheme in ("http", "https") and bool(p.netloc)

    def _validate_scrape_opts(_formats, _includeHtml, _includeMarkdown, _includeText, _onlyMainContent, _waitFor, _timeout, _headers, _cookies, _proxy):
        allowed_formats = {"html", "text", "markdown"}
        if _formats is not None:
            if not isinstance(_formats, list):
                return _err("VALIDATION_ERROR", "formats must be an array of strings")
            for x in _formats:
                if x not in allowed_formats:
                    return _err("VALIDATION_ERROR", "formats contains unsupported values", unsupported=x)
        for nm, val in [("includeHtml", _includeHtml), ("includeMarkdown", _includeMarkdown), ("includeText", _includeText), ("onlyMainContent", _onlyMainContent)]:
            if val is not None and not isinstance(val, bool):
                return _err("VALIDATION_ERROR", f"{nm} must be a boolean")
        for nm, val in [("waitFor", _waitFor), ("timeout", _timeout)]:
            if val is not None:
                if not isinstance(val, int):
                    return _err("VALIDATION_ERROR", f"{nm} must be an integer")
                if val < 0:
                    return _err("VALIDATION_ERROR", f"{nm} must be >= 0")
        if _headers is not None:
            if not isinstance(_headers, dict):
                return _err("VALIDATION_ERROR", "headers must be an object")
            for k, v in _headers.items():
                if not isinstance(k, str) or not isinstance(v, str):
                    return _err("VALIDATION_ERROR", "headers must be a string->string object")
        if _cookies is not None:
            if not isinstance(_cookies, list):
                return _err("VALIDATION_ERROR", "cookies must be an array")
            for c in _cookies:
                if not isinstance(c, dict):
                    return _err("VALIDATION_ERROR", "cookies items must be objects")
                if "name" not in c or "value" not in c:
                    return _err("VALIDATION_ERROR", "cookies are missing", missing=["name", "value"])
                if not isinstance(c.get("name"), str) or not isinstance(c.get("value"), str):
                    return _err("VALIDATION_ERROR", "cookies name/value must be strings")
                for optk in ("domain", "path"):
                    if optk in c and c[optk] is not None and not isinstance(c[optk], str):
                        return _err("VALIDATION_ERROR", f"cookies.{optk} must be a string")
                extra_keys = set(c.keys()) - {"name", "value", "domain", "path"}
                if extra_keys:
                    return _err("VALIDATION_ERROR", "cookies contains unsupported fields", fields=sorted(extra_keys))
        if _proxy is not None:
            if _proxy not in ("none", "auto"):
                return _err("VALIDATION_ERROR", "proxy must be one of: none, auto")
        return None

    def _pick_auth_context(api_keys, workspaces):
        # Ambient auth: choose any active api_key whose workspace is active.
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
        for k in api_keys:
            if not isinstance(k, dict): 
                continue
            if k.get("status") != "active":
                continue
            ws = ws_by_id.get(k.get("workspace_id"))
            if ws and ws.get("status") == "active":
                return k, ws
        return None, None

    def _ensure_usage_month(ws):
        m = _month()
        if ws.get("usage_month") != m:
            ws["usage_month"] = m
            ws["pages_used"] = 0
            ws["llm_tokens_used"] = 0

    def _gen_id(prefix):
        return prefix + "_" + hashlib.sha256((prefix + ":" + _now() + ":" + os.urandom(16).hex()).encode("utf-8")).hexdigest()[:24]

    # Prepare request log collection (not declared in schema, but required if present)
    # We'll use request_logs.json if it exists; otherwise create it on first write.
    req_logs = _load("request_logs.json")
    if not isinstance(req_logs, list):
        req_logs = []

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    jobs = _load("jobs.json")
    job_items = _load("job_items.json")
    pages = _load("pages.json")

    # Authenticate
    api_key_row, ws = _pick_auth_context(api_keys, workspaces)
    if not api_key_row or not ws:
        # log
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_scrape",
            "api_key_id": None,
            "workspace_id": None,
            "status": "error",
            "error_code": "UNAUTHORIZED",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "No active API key/workspace available for this request")

    # Validate inputs
    if not _is_abs_http_url(url):
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_scrape",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "url is missing/invalid")

    if webhook is not None:
        if not isinstance(webhook, str) or not re.match(r"^https?://", webhook):
            req_logs.append({
                "id": _gen_id("req"),
                "endpoint": "firecrawl_scrape",
                "api_key_id": api_key_row.get("id"),
                "workspace_id": ws.get("id"),
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - _t0) * 1000),
                "created_at": _now(),
            })
            _save("request_logs.json", req_logs)
            return _err("VALIDATION_ERROR", "webhook_url is invalid; must start with http:// or https://")

    if webhookSecret is not None and not isinstance(webhookSecret, str):
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_scrape",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "webhookSecret must be a string")

    if priority is None:
        priority = 0
    if not isinstance(priority, int) or priority < -10 or priority > 10:
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_scrape",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "priority must be between -10 and 10")

    v = _validate_scrape_opts(formats, includeHtml, includeMarkdown, includeText, onlyMainContent, waitFor, timeout, headers, cookies, proxy)
    if v:
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_scrape",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": v["error"]["code"],
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return v

    # Determine which formats to include/store
    fmts = set(formats or [])
    if includeHtml: fmts.add("html")
    if includeMarkdown: fmts.add("markdown")
    if includeText: fmts.add("text")
    if not fmts:
        fmts = {"markdown"}  # sensible default without contradicting schema

    # Quota check (this job will fetch at least 1 page; no LLM usage)
    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
    ws_row = ws_by_id.get(ws.get("id"))
    if not ws_row:
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_scrape",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "NOT_FOUND",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("NOT_FOUND", "Workspace not found")

    _ensure_usage_month(ws_row)
    if not isinstance(ws_row.get("monthly_page_limit"), int) or ws_row.get("monthly_page_limit") < 0:
        ws_row["monthly_page_limit"] = 0
    if not isinstance(ws_row.get("pages_used"), int) or ws_row.get("pages_used") < 0:
        ws_row["pages_used"] = 0

    would_exceed_pages = (ws_row["pages_used"] + 1) > ws_row["monthly_page_limit"]
    # Create job
    jid = _gen_id("job")
    now = _now()
    job = {
        "id": jid,
        "workspace_id": ws_row["id"],
        "api_key_id": api_key_row.get("id"),
        "tool": "firecrawl_scrape",
        "status": "queued",
        "priority": priority,
        "input": {
            "url": url,
            "formats": sorted(fmts),
            "onlyMainContent": bool(onlyMainContent) if onlyMainContent is not None else None,
            "includeHtml": bool(includeHtml) if includeHtml is not None else None,
            "includeMarkdown": bool(includeMarkdown) if includeMarkdown is not None else None,
            "includeText": bool(includeText) if includeText is not None else None,
            "waitFor": waitFor,
            "timeout": timeout,
            "headers": headers,
            "cookies": cookies,
            "proxy": proxy,
        },
        "webhook_url": webhook,
        "webhook_secret": webhookSecret,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "result_summary": None,
        "pages_fetched": 0,
        "llm_tokens_used": 0,
        "created_at": now,
        "updated_at": now,
    }

    # If quota exceeded, force into failed job
    if would_exceed_pages:
        job["status"] = "failed"
        job["started_at"] = now
        job["finished_at"] = now
        job["error_code"] = "quota_exceeded"
        job["error_message"] = "Monthly page quota exceeded"
        job["pages_fetched"] = 0
        job["result_summary"] = {"quota": {"type": "pages", "monthly_limit": ws_row["monthly_page_limit"], "used": ws_row["pages_used"]}}
        jobs.append(job)
        # webhook attempt on terminal completion, exactly once
        if webhook:
            rs = job.get("result_summary") or {}
            rs["webhook"] = {"attempted_at": _now(), "status_code": 0, "error": "offline_delivery_not_supported"}
            job["result_summary"] = rs
        # persist
        api_key_row["last_used_at"] = _now()
        api_key_row["updated_at"] = _now()
        ws_row["updated_at"] = _now()
        _save("jobs.json", jobs)
        _save("api_keys.json", api_keys)
        _save("workspaces.json", workspaces)

        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_scrape",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws_row.get("id"),
            "status": "error",
            "error_code": "QUOTA_EXCEEDED",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("QUOTA_EXCEEDED", "Monthly page quota exceeded")

    # Synchronous execution: queued->running->succeeded, create page + job_item
    # Transition queued->running
    job["status"] = "running"
    job["started_at"] = _now()
    job["updated_at"] = _now()

    # Create page artifact
    pid = _gen_id("page")
    parsed = urllib.parse.urlparse(url)
    canonical_url = urllib.parse.urlunparse(parsed._replace(fragment=""))
    title = parsed.netloc
    # Deterministic-ish dummy content; real network not available
    base_text = f"Scraped content for {canonical_url}"
    html_val = f"<html><head><title>{title}</title></head><body><main><p>{base_text}</p></main></body></html>"
    text_val = base_text
    md_val = f"# {title}\n\n{base_text}\n"

    page = {
        "id": pid,
        "workspace_id": ws_row["id"],
        "source_job_id": jid,
        "url": canonical_url,
        "fetched_url": url,
        "status": "stored",
        "content_type": "text/html",
        "language": None,
        "title": title,
        "html": html_val if "html" in fmts else None,
        "text": text_val if "text" in fmts else None,
        "markdown": md_val if "markdown" in fmts else None,
        "metadata": {
            "onlyMainContent": bool(onlyMainContent) if onlyMainContent is not None else False,
            "headers": headers or {},
            "proxy": proxy or "none",
            "timing": {"waitFor_ms": waitFor or 0, "timeout_ms": timeout or 0},
        },
        "extracted_data": None,
        "llms_txt": None,
        "content_sha256": hashlib.sha256((text_val).encode("utf-8")).hexdigest() if text_val else hashlib.sha256((md_val).encode("utf-8")).hexdigest(),
        "created_at": _now(),
        "updated_at": _now(),
    }

    # Unique(workspace_id, url, content_sha256) where content_sha256 not null
    for p in pages:
        if not isinstance(p, dict):
            continue
        if p.get("workspace_id") == page["workspace_id"] and p.get("url") == page["url"] and p.get("content_sha256") and p.get("content_sha256") == page["content_sha256"]:
            # Reuse existing artifact; still create job_item pointing to it.
            pid = p.get("id")
            page = None
            break

    if page is not None:
        pages.append(page)

    # Create job item
    jiid = _gen_id("jitem")
    job_item = {
        "id": jiid,
        "job_id": jid,
        "sequence": 0,
        "url": canonical_url,
        "parent_url": None,
        "depth": None,
        "kind": "seed",
        "status": "succeeded",
        "http_status": 200,
        "title": title,
        "description": None,
        "page_id": pid,
        "error_message": None,
        "created_at": _now(),
        "updated_at": _now(),
    }
    job_items.append(job_item)

    # Complete job
    job["status"] = "succeeded"
    job["finished_at"] = _now()
    job["updated_at"] = _now()
    job["pages_fetched"] = 1
    job["llm_tokens_used"] = 0
    job["result_summary"] = {"pages_fetched": 1, "page_id": pid}

    # Quota accounting on completion
    ws_row["pages_used"] = int(ws_row.get("pages_used") or 0) + job["pages_fetched"]
    ws_row["llm_tokens_used"] = int(ws_row.get("llm_tokens_used") or 0) + job["llm_tokens_used"]
    ws_row["updated_at"] = _now()

    # Webhook attempt exactly once on terminal completion
    if webhook:
        rs = job.get("result_summary") or {}
        rs["webhook"] = {"attempted_at": _now(), "status_code": 0, "error": "offline_delivery_not_supported"}
        job["result_summary"] = rs

    jobs.append(job)

    # Update key last_used_at
    api_key_row["last_used_at"] = _now()
    api_key_row["updated_at"] = _now()

    # Persist all
    _save("pages.json", pages)
    _save("job_items.json", job_items)
    _save("jobs.json", jobs)
    _save("workspaces.json", workspaces)
    _save("api_keys.json", api_keys)

    # Log request
    req_logs.append({
        "id": _gen_id("req"),
        "endpoint": "firecrawl_scrape",
        "api_key_id": api_key_row.get("id"),
        "workspace_id": ws_row.get("id"),
        "status": "ok",
        "job_id": jid,
        "latency_ms": int((time.time() - _t0) * 1000),
        "created_at": _now(),
    })
    _save("request_logs.json", req_logs)

    # Response: return job metadata + content
    out_page = None
    # Ensure we return the stored page artifact content based on fmts
    for p in pages:
        if isinstance(p, dict) and p.get("id") == pid:
            out_page = p
            break
    if not out_page:
        return _err("NOT_FOUND", "Page artifact not found after scrape")

    data = {
        "url": out_page.get("url"),
        "title": out_page.get("title"),
        "metadata": out_page.get("metadata") or {},
    }
    if "html" in fmts:
        data["html"] = out_page.get("html")
    if "markdown" in fmts:
        data["markdown"] = out_page.get("markdown")
    if "text" in fmts:
        data["text"] = out_page.get("text")

    return {
        "success": True,
        "job": {"id": jid, "status": "succeeded", "tool": "firecrawl_scrape"},
        "data": data,
        "page_id": pid,
    }

def firecrawl_map(url, includeSitemap=None, includeLinks=None, limit=None, cursor=None, allowExternalDomains=None, includeSubdomains=None, pathIncludes=None, pathExcludes=None, maxDepth=None, **_extra):
    import json, os, datetime, time, re, hashlib, urllib.parse

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0122000" if __import__("os").path.isdir("./environment_mix/0122000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _gen_id(prefix):
        return prefix + "_" + hashlib.sha256((prefix + ":" + _now() + ":" + os.urandom(16).hex()).encode("utf-8")).hexdigest()[:24]

    def _is_abs_http_url(u):
        if not isinstance(u, str) or not u:
            return False
        try:
            p = urllib.parse.urlparse(u)
        except Exception:
            return False
        return p.scheme in ("http", "https") and bool(p.netloc)

    def _pick_auth_context(api_keys, workspaces):
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            ws = ws_by_id.get(k.get("workspace_id"))
            if ws and ws.get("status") == "active":
                return k, ws
        return None, None

    # request log
    req_logs = _load("request_logs.json")
    if not isinstance(req_logs, list):
        req_logs = []

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    jobs = _load("jobs.json")
    job_items = _load("job_items.json")

    api_key_row, ws = _pick_auth_context(api_keys, workspaces)
    if not api_key_row or not ws:
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_map",
            "api_key_id": None,
            "workspace_id": None,
            "status": "error",
            "error_code": "UNAUTHORIZED",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "No active API key/workspace available for this request")

    # validations
    if not _is_abs_http_url(url):
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_map",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "url is invalid")

    if limit is None:
        limit = 50
    if not isinstance(limit, int) or limit < 1 or limit > 1000:
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_map",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "limit is out of range (1..1000)")

    if maxDepth is None:
        maxDepth = 2
    if not isinstance(maxDepth, int) or maxDepth < 0 or maxDepth > 20:
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_map",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "maxDepth is out of range (0..20)")

    for nm, val in [("includeSitemap", includeSitemap), ("includeLinks", includeLinks), ("allowExternalDomains", allowExternalDomains), ("includeSubdomains", includeSubdomains)]:
        if val is not None and not isinstance(val, bool):
            req_logs.append({
                "id": _gen_id("req"),
                "endpoint": "firecrawl_map",
                "api_key_id": api_key_row.get("id"),
                "workspace_id": ws.get("id"),
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - _t0) * 1000),
                "created_at": _now(),
            })
            _save("request_logs.json", req_logs)
            return _err("VALIDATION_ERROR", f"{nm} must be a boolean")

    if pathIncludes is not None and (not isinstance(pathIncludes, list) or any(not isinstance(x, str) for x in pathIncludes)):
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_map",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "pathIncludes must be an array of strings")

    if pathExcludes is not None and (not isinstance(pathExcludes, list) or any(not isinstance(x, str) for x in pathExcludes)):
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_map",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "pathExcludes must be an array of strings")

    if cursor is not None and not isinstance(cursor, str):
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_map",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "cursor must be a string")

    # Create job row (async by nature, but we will pre-populate deterministic discovered URLs)
    parsed = urllib.parse.urlparse(url)
    base_host = parsed.netloc.lower()
    base_scheme = parsed.scheme
    base_root = f"{base_scheme}://{base_host}"
    base_path = parsed.path if parsed.path else "/"
    if not base_path.startswith("/"):
        base_path = "/" + base_path
    base_dir = base_path.rsplit("/", 1)[0] if "/" in base_path else "/"
    if not base_dir:
        base_dir = "/"

    jid = _gen_id("job")
    now = _now()
    job = {
        "id": jid,
        "workspace_id": ws.get("id"),
        "api_key_id": api_key_row.get("id"),
        "tool": "firecrawl_map",
        "status": "succeeded",
        "priority": 0,
        "input": {
            "url": url,
            "includeSitemap": bool(includeSitemap) if includeSitemap is not None else False,
            "includeLinks": bool(includeLinks) if includeLinks is not None else True,
            "allowExternalDomains": bool(allowExternalDomains) if allowExternalDomains is not None else False,
            "includeSubdomains": bool(includeSubdomains) if includeSubdomains is not None else False,
            "pathIncludes": pathIncludes or [],
            "pathExcludes": pathExcludes or [],
            "maxDepth": maxDepth,
        },
        "webhook_url": None,
        "webhook_secret": None,
        "started_at": now,
        "finished_at": now,
        "error_code": None,
        "error_message": None,
        "result_summary": None,
        "pages_fetched": 0,
        "llm_tokens_used": 0,
        "created_at": now,
        "updated_at": now,
    }

    # Deterministic URL discovery (offline): generate a stable list
    # includeLinks controls whether we generate link-like paths; includeSitemap adds sitemap-ish paths
    inc_links = True if includeLinks is None else bool(includeLinks)
    inc_sitemap = False if includeSitemap is None else bool(includeSitemap)
    allow_ext = False if allowExternalDomains is None else bool(allowExternalDomains)

    candidates = []
    # always include the seed itself
    candidates.append(urllib.parse.urlunparse(parsed._replace(fragment="")))
    if inc_sitemap:
        candidates.extend([
            base_root + "/sitemap.xml",
            base_root + "/robots.txt",
        ])
    if inc_links:
        # generate up to ~200 candidates based on maxDepth
        for d in range(0, maxDepth + 1):
            for i in range(1, 1 + min(50, 10 * (d + 1))):
                candidates.append(base_root + base_dir + f"/page-{d}-{i}")
        candidates.append(base_root + "/about")
        candidates.append(base_root + "/contact")

    # optionally external
    if allow_ext:
        candidates.append("https://example.com/")

    # de-dupe, normalize, apply filters
    def _path_ok(u):
        try:
            p = urllib.parse.urlparse(u)
        except Exception:
            return False
        path = p.path or "/"
        if pathExcludes:
            for ex in pathExcludes:
                if ex and ex in path:
                    return False
        if pathIncludes:
            inc = False
            for incs in pathIncludes:
                if incs and incs in path:
                    inc = True
                    break
            if not inc:
                return False
        return True

    def _domain_ok(u):
        try:
            p = urllib.parse.urlparse(u)
        except Exception:
            return False
        host = (p.netloc or "").lower()
        if allow_ext:
            return True
        if includeSubdomains:
            return host == base_host or host.endswith("." + base_host)
        return host == base_host

    uniq = []
    seen = set()
    for u in candidates:
        if not _is_abs_http_url(u):
            continue
        if not _domain_ok(u):
            continue
        if not _path_ok(u):
            continue
        nu = urllib.parse.urlunparse(urllib.parse.urlparse(u)._replace(fragment=""))
        if nu in seen:
            continue
        seen.add(nu)
        uniq.append(nu)

    # store as job_items(kind=discovered) (no pages unless scrape is specified; this tool has no scrape options)
    # sequence stable
    for idx, u in enumerate(uniq):
        job_items.append({
            "id": _gen_id("jitem"),
            "job_id": jid,
            "sequence": idx,
            "url": u,
            "parent_url": url if idx != 0 else None,
            "depth": 0 if idx == 0 else 1,
            "kind": "discovered",
            "status": "succeeded",
            "http_status": None,
            "title": None,
            "description": None,
            "page_id": None,
            "error_message": None,
            "created_at": _now(),
            "updated_at": _now(),
        })

    job["result_summary"] = {"discovered": len(uniq)}
    jobs.append(job)

    api_key_row["last_used_at"] = _now()
    api_key_row["updated_at"] = _now()
    _save("jobs.json", jobs)
    _save("job_items.json", job_items)
    _save("api_keys.json", api_keys)

    # paginate results for this response
    start = 0
    if cursor:
        if not cursor.startswith("i:"):
            req_logs.append({
                "id": _gen_id("req"),
                "endpoint": "firecrawl_map",
                "api_key_id": api_key_row.get("id"),
                "workspace_id": ws.get("id"),
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - _t0) * 1000),
                "created_at": _now(),
            })
            _save("request_logs.json", req_logs)
            return _err("VALIDATION_ERROR", "cursor is invalid")
        try:
            start = int(cursor.split(":", 1)[1])
        except Exception:
            start = -1
        if start < 0:
            req_logs.append({
                "id": _gen_id("req"),
                "endpoint": "firecrawl_map",
                "api_key_id": api_key_row.get("id"),
                "workspace_id": ws.get("id"),
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - _t0) * 1000),
                "created_at": _now(),
            })
            _save("request_logs.json", req_logs)
            return _err("VALIDATION_ERROR", "cursor is invalid")

    end = start + limit
    page_urls = uniq[start:end]
    has_more = end < len(uniq)
    next_cursor = f"i:{end}" if has_more else None

    req_logs.append({
        "id": _gen_id("req"),
        "endpoint": "firecrawl_map",
        "api_key_id": api_key_row.get("id"),
        "workspace_id": ws.get("id"),
        "status": "ok",
        "job_id": jid,
        "latency_ms": int((time.time() - _t0) * 1000),
        "created_at": _now(),
    })
    _save("request_logs.json", req_logs)

    return {
        "success": True,
        "job": {"id": jid, "status": "succeeded", "tool": "firecrawl_map"},
        "data": {"urls": page_urls},
        "metadata": {"total": len(uniq), "limit": limit, "has_more": has_more, "next_cursor": next_cursor},
    }

def firecrawl_crawl(url, maxDepth=None, limit=None, includeSubdomains=None, allowExternalDomains=None, pathIncludes=None, pathExcludes=None, webhook=None, webhookSecret=None, priority=None, scrapeOptions=None, **_extra):
    import json, os, datetime, time, re, hashlib, urllib.parse

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0122000" if __import__("os").path.isdir("./environment_mix/0122000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _month():
        return datetime.datetime.utcnow().strftime("%Y-%m")

    def _gen_id(prefix):
        return prefix + "_" + hashlib.sha256((prefix + ":" + _now() + ":" + os.urandom(16).hex()).encode("utf-8")).hexdigest()[:24]

    def _is_abs_http_url(u):
        if not isinstance(u, str) or not u:
            return False
        try:
            p = urllib.parse.urlparse(u)
        except Exception:
            return False
        return p.scheme in ("http", "https") and bool(p.netloc)

    def _validate_proxy(v):
        if v is None:
            return None
        if v not in ("none", "auto"):
            return _err("VALIDATION_ERROR", "proxy must be one of: none, auto")
        return None

    def _validate_scrape_options(o):
        if o is None:
            return None, None
        if not isinstance(o, dict):
            return _err("VALIDATION_ERROR", "scrapeOptions must be an object"), None
        allowed_keys = {"formats", "onlyMainContent", "includeHtml", "includeMarkdown", "includeText", "waitFor", "timeout", "headers", "proxy"}
        extra = set(o.keys()) - allowed_keys
        if extra:
            return _err("VALIDATION_ERROR", "scrapeOptions contains unsupported fields", fields=sorted(extra)), None
        fmts = o.get("formats")
        if fmts is not None:
            if not isinstance(fmts, list) or any(x not in ("html", "text", "markdown") for x in fmts):
                return _err("VALIDATION_ERROR", "scrapeOptions.formats is invalid"), None
        for nm in ("onlyMainContent", "includeHtml", "includeMarkdown", "includeText"):
            v = o.get(nm)
            if v is not None and not isinstance(v, bool):
                return _err("VALIDATION_ERROR", f"scrapeOptions.{nm} must be a boolean"), None
        for nm in ("waitFor", "timeout"):
            v = o.get(nm)
            if v is not None:
                if not isinstance(v, int) or v < 0:
                    return _err("VALIDATION_ERROR", f"scrapeOptions.{nm} must be an integer >= 0"), None
        hdrs = o.get("headers")
        if hdrs is not None:
            if not isinstance(hdrs, dict) or any((not isinstance(k, str) or not isinstance(v, str)) for k, v in hdrs.items()):
                return _err("VALIDATION_ERROR", "scrapeOptions.headers must be a string->string object"), None
        pv = _validate_proxy(o.get("proxy"))
        if pv:
            return pv, None
        # compute effective formats
        eff = set(fmts or [])
        if o.get("includeHtml"): eff.add("html")
        if o.get("includeMarkdown"): eff.add("markdown")
        if o.get("includeText"): eff.add("text")
        if not eff:
            eff = {"markdown"}
        return None, {"effective_formats": sorted(eff)}

    def _pick_auth_context(api_keys, workspaces):
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            ws = ws_by_id.get(k.get("workspace_id"))
            if ws and ws.get("status") == "active":
                return k, ws
        return None, None

    def _ensure_usage_month(ws):
        m = _month()
        if ws.get("usage_month") != m:
            ws["usage_month"] = m
            ws["pages_used"] = 0
            ws["llm_tokens_used"] = 0

    req_logs = _load("request_logs.json")
    if not isinstance(req_logs, list):
        req_logs = []

    api_keys = _load("api_keys.json")
    workspaces = _load("workspaces.json")
    jobs = _load("jobs.json")
    job_items = _load("job_items.json")
    pages = _load("pages.json")

    api_key_row, ws = _pick_auth_context(api_keys, workspaces)
    if not api_key_row or not ws:
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_crawl",
            "api_key_id": None,
            "workspace_id": None,
            "status": "error",
            "error_code": "UNAUTHORIZED",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("UNAUTHORIZED", "No active API key/workspace available for this request")

    if not _is_abs_http_url(url):
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_crawl",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "url is invalid")

    if maxDepth is None:
        maxDepth = 2
    if not isinstance(maxDepth, int) or maxDepth < 0 or maxDepth > 20:
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_crawl",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "maxDepth is invalid (0..20)")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit < 1 or limit > 10000:
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_crawl",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "limit is invalid (1..10000)")

    if priority is None:
        priority = 0
    if not isinstance(priority, int) or priority < -10 or priority > 10:
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_crawl",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "priority is invalid (-10..10)")

    if webhook is not None:
        if not isinstance(webhook, str) or not re.match(r"^https?://", webhook):
            req_logs.append({
                "id": _gen_id("req"),
                "endpoint": "firecrawl_crawl",
                "api_key_id": api_key_row.get("id"),
                "workspace_id": ws.get("id"),
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - _t0) * 1000),
                "created_at": _now(),
            })
            _save("request_logs.json", req_logs)
            return _err("VALIDATION_ERROR", "webhook must be a valid http(s) URL")

    if webhookSecret is not None and not isinstance(webhookSecret, str):
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_crawl",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "webhookSecret must be a string")

    for nm, val in [("includeSubdomains", includeSubdomains), ("allowExternalDomains", allowExternalDomains)]:
        if val is not None and not isinstance(val, bool):
            req_logs.append({
                "id": _gen_id("req"),
                "endpoint": "firecrawl_crawl",
                "api_key_id": api_key_row.get("id"),
                "workspace_id": ws.get("id"),
                "status": "error",
                "error_code": "VALIDATION_ERROR",
                "latency_ms": int((time.time() - _t0) * 1000),
                "created_at": _now(),
            })
            _save("request_logs.json", req_logs)
            return _err("VALIDATION_ERROR", f"{nm} must be a boolean")

    if pathIncludes is not None and (not isinstance(pathIncludes, list) or any(not isinstance(x, str) for x in pathIncludes)):
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_crawl",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "pathIncludes must be an array of strings")

    if pathExcludes is not None and (not isinstance(pathExcludes, list) or any(not isinstance(x, str) for x in pathExcludes)):
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_crawl",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "VALIDATION_ERROR",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("VALIDATION_ERROR", "pathExcludes must be an array of strings")

    v, scrape_meta = _validate_scrape_options(scrapeOptions)
    if v:
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_crawl",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": v["error"]["code"],
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return v

    # Workspace + quota precheck: worst-case pages = limit
    ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
    ws_row = ws_by_id.get(ws.get("id"))
    if not ws_row:
        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_crawl",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws.get("id"),
            "status": "error",
            "error_code": "NOT_FOUND",
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("NOT_FOUND", "Workspace not found")

    _ensure_usage_month(ws_row)
    would_exceed_pages = (int(ws_row.get("pages_used") or 0) + int(limit)) > int(ws_row.get("monthly_page_limit") or 0)

    jid = _gen_id("job")
    now = _now()
    job = {
        "id": jid,
        "workspace_id": ws_row["id"],
        "api_key_id": api_key_row.get("id"),
        "tool": "firecrawl_crawl",
        "status": "queued",
        "priority": priority,
        "input": {
            "url": url,
            "maxDepth": maxDepth,
            "limit": limit,
            "includeSubdomains": bool(includeSubdomains) if includeSubdomains is not None else False,
            "allowExternalDomains": bool(allowExternalDomains) if allowExternalDomains is not None else False,
            "pathIncludes": pathIncludes or [],
            "pathExcludes": pathExcludes or [],
            "scrapeOptions": scrapeOptions,
        },
        "webhook_url": webhook,
        "webhook_secret": webhookSecret,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "result_summary": None,
        "pages_fetched": 0,
        "llm_tokens_used": 0,
        "created_at": now,
        "updated_at": now,
    }

    # Always create at least one seed job_item
    seed_item = {
        "id": _gen_id("jitem"),
        "job_id": jid,
        "sequence": 0,
        "url": urllib.parse.urlunparse(urllib.parse.urlparse(url)._replace(fragment="")),
        "parent_url": None,
        "depth": 0,
        "kind": "seed",
        "status": "queued",
        "http_status": None,
        "title": None,
        "description": None,
        "page_id": None,
        "error_message": None,
        "created_at": _now(),
        "updated_at": _now(),
    }

    jobs.append(job)
    job_items.append(seed_item)

    # If quota exceeded, fail immediately and do not fetch pages
    if would_exceed_pages:
        job["status"] = "failed"
        job["started_at"] = _now()
        job["finished_at"] = _now()
        job["error_code"] = "quota_exceeded"
        job["error_message"] = "Monthly page quota exceeded"
        job["updated_at"] = _now()
        job["result_summary"] = {"quota": {"type": "pages", "monthly_limit": ws_row.get("monthly_page_limit"), "used": ws_row.get("pages_used"), "requested": limit}}
        # webhook attempt on terminal completion
        if webhook:
            rs = job.get("result_summary") or {}
            rs["webhook"] = {"attempted_at": _now(), "status_code": 0, "error": "offline_delivery_not_supported"}
            job["result_summary"] = rs
        api_key_row["last_used_at"] = _now()
        api_key_row["updated_at"] = _now()
        _save("jobs.json", jobs)
        _save("job_items.json", job_items)
        _save("api_keys.json", api_keys)

        req_logs.append({
            "id": _gen_id("req"),
            "endpoint": "firecrawl_crawl",
            "api_key_id": api_key_row.get("id"),
            "workspace_id": ws_row.get("id"),
            "status": "error",
            "error_code": "QUOTA_EXCEEDED",
            "job_id": jid,
            "latency_ms": int((time.time() - _t0) * 1000),
            "created_at": _now(),
        })
        _save("request_logs.json", req_logs)
        return _err("QUOTA_EXCEEDED", "Monthly page quota exceeded", job_id=jid)

    # Offline "processing": mark as succeeded, create up to min(limit, 25) discovered crawl_page items
    # and pages only if scrapeOptions present.
    parsed = urllib.parse.urlparse(url)
    base_host = parsed.netloc.lower()
    base_scheme = parsed.scheme
    base_root = f"{base_scheme}://{base_host}"
    base_path = parsed.path if parsed.path else "/"
    if not base_path.startswith("/"):
        base_path = "/" + base_path
    base_dir = base_path.rsplit("/", 1)[0] if "/" in base_path else "/"
    if not base_dir:
        base_dir = "/"

    def _path_ok(u):
        p = urllib.parse.urlparse(u)
        path = p.path or "/"
        if pathExcludes:
            for ex in pathExcludes:
                if ex and ex in path:
                    return False
        if pathIncludes:
            for inc in pathIncludes:
                if inc and inc in path:
                    return True
            return False
        return True

    # transition queued->running
    job["status"] = "running"
    job["started_at"] = _now()
    job["updated_at"] = _now()

    eff_limit = min(limit, 25)  # keep datastore bounded
    eff_depth = maxDepth
    discovered_urls = []
    for d in range(0, eff_depth + 1):
        for i in range(1, 1 + max(1, eff_limit // (eff_depth + 1))):
            discovered_urls.append(base_root + base_dir + f"/crawl-{d}-{i}")
            if len(discovered_urls) >= eff_limit:
                break
        if len(discovered_urls) >= eff_limit:
            break

    # seed item succeeds too
    seed_item["status"] = "succeeded"
    seed_item["updated_at"] = _now()

    pages_created = 0
    seq = 1
    eff_formats = set((scrape_meta or {}).get("effective_formats") or [])
    for u in discovered_urls:
        if not _path_ok(u):
            continue
        ji = {
            "id": _gen_id("jitem"),
            "job_id": jid,
            "sequence": seq,
            "url": u,
            "parent_url": seed_item["url"],
            "depth": min(eff_depth, 1),
            "kind": "crawl_page",
            "status": "succeeded",
            "http_status": 200,
            "title": urllib.parse.urlparse(u).path.rsplit("/", 1)[-1] or base_host,
            "description": None,
            "page_id": None,
            "error_message": None,
            "created_at": _now(),
            "updated_at": _now(),
        }
        # If scraping configured, create a page and link it
        if scrapeOptions is not None:
            pid = _gen_id("page")
            title = ji["title"]
            base_text = f"Crawled content for {u}"
            html_val = f"<html><head><title>{title}</title></head><body><main><p>{base_text}</p></main></body></html>"
            text_val = base_text
            md_val = f"# {title}\n\n{base_text}\n"
            page = {
                "id": pid,
                "workspace_id": ws_row["id"],
                "source_job_id": jid,
                "url": u,
                "fetched_url": u,
                "status": "stored",
                "content_type": "text/html",
                "language": None,
                "title": title,
                "html": html_val if "html" in eff_formats else None,
                "text": text_val if "text" in eff_formats else None,
                "markdown": md_val if "markdown" in eff_formats else None,
                "metadata": {
                    "crawl": {"depth": ji["depth"], "seed": seed_item["url"]},
                    "scrapeOptions": scrapeOptions,
                },
                "extracted_data": None,
                "llms_txt": None,
                "content_sha256": hashlib.sha256((text_val).encode("utf-8")).hexdigest(),
                "created_at": _now(),
                "updated_at": _now(),
            }
            # uniqueness check
            dup = None
            for p in pages:
                if isinstance(p, dict) and p.get("workspace_id") == page["workspace_id"] and p.get("url") == page["url"] and p.get("content_sha256") == page["content_sha256"] and p.get("content_sha256") is not None:
                    dup = p
                    break
            if dup:
                pid = dup.get("id")
            else:
                pages.append(page)
                pages_created += 1
            ji["page_id"] = pid

        job_items.append(ji)
        seq += 1
        if seq > eff_limit:
            break

    # complete job: pages_fetched counts fetched pages (items crawled)
    fetched = max(0, seq - 1)
    job["status"] = "succeeded"
    job["finished_at"] = _now()
    job["updated_at"] = _now()
    job["pages_fetched"] = fetched
    job["llm_tokens_used"] = 0
    job["result_summary"] = {"items": fetched + 1, "pages_fetched": fetched, "pages_created": pages_created}

    # Quota accounting on completion
    ws_row["pages_used"] = int(ws_row.get("pages_used") or 0) + job["pages_fetched"]
    ws_row["llm_tokens_used"] = int(ws_row.get("llm_tokens_used") or 0) + job["llm_tokens_used"]
    ws_row["updated_at"] = _now()

    # webhook attempt exactly once on terminal completion
    if webhook:
        rs = job.get("result_summary") or {}
        rs["webhook"] = {"attempted_at": _now(), "status_code": 0, "error": "offline_delivery_not_supported"}
        job["result_summary"] = rs

    api_key_row["last_used_at"] = _now()
    api_key_row["updated_at"] = _now()

    _save("pages.json", pages)
    _save("jobs.json", jobs)
    _save("job_items.json", job_items)
    _save("workspaces.json", workspaces)
    _save("api_keys.json", api_keys)

    req_logs.append({
        "id": _gen_id("req"),
        "endpoint": "firecrawl_crawl",
        "api_key_id": api_key_row.get("id"),
        "workspace_id": ws_row.get("id"),
        "status": "ok",
        "job_id": jid,
        "latency_ms": int((time.time() - _t0) * 1000),
        "created_at": _now(),
    })
    _save("request_logs.json", req_logs)

    return {"success": True, "job": {"id": jid, "status": job["status"], "tool": "firecrawl_crawl"}}

def firecrawl_check_batch_status(jobId, includePages=None, limit=None, cursor=None, status=None, **_extra):
    import json, os, datetime, time, re

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0122000" if __import__("os").path.isdir("./environment_mix/0122000") else "/app/database")
    _t0 = time.time()

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_month_bucket(ws):
        # Reset usage bucket if month changed
        now_m = datetime.datetime.utcnow().strftime("%Y-%m")
        if isinstance(ws, dict) and ws.get("usage_month") != now_m:
            ws["usage_month"] = now_m
            ws["pages_used"] = 0
            ws["llm_tokens_used"] = 0
            ws["updated_at"] = _now_iso()
        return ws

    def _log(endpoint, api_key_id, workspace_id, status_txt, error_code=None):
        fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
                "timestamp": _now_iso(),
                "status": status_txt,
                "error_code": error_code,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save(fname, logs)

    def _resolve_auth_for_job(job):
        # Ambient auth: pick an active api key whose workspace is active and matches job.workspace_id.
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        ws_id = job.get("workspace_id") if isinstance(job, dict) else None
        ws = None
        if isinstance(workspaces, list) and isinstance(ws_id, str):
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
        if not ws or ws.get("status") != "active":
            return None, None, api_keys, workspaces
        if not isinstance(api_keys, list):
            api_keys = []
        key = next((k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == ws_id and k.get("status") == "active"), None)
        if not key:
            return None, ws, api_keys, workspaces
        return key, ws, api_keys, workspaces

    # ---- validate inputs ----
    if not isinstance(jobId, str) or not jobId.strip():
        _log("firecrawl_check_batch_status", None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "jobId must be a non-empty string")

    # The vendor schema wants fc_job_*; but the audit shows callers can pass workspace-like ids.
    # Accept any non-empty string; only enforce the regex when it *does* look like it is intended to be a job id.
    if jobId.startswith("fc_job_"):
        if not re.match(r"^fc_job_[A-Za-z0-9]+$", jobId):
            _log("firecrawl_check_batch_status", None, None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "jobId does not match required pattern ^fc_job_[A-Za-z0-9]+$")

    if includePages is not None and not isinstance(includePages, bool):
        _log("firecrawl_check_batch_status", None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "includePages must be a boolean")

    if limit is None:
        limit = 100
    if not isinstance(limit, int) or limit <= 0 or limit > 5000:
        _log("firecrawl_check_batch_status", None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "limit must be an integer between 1 and 5000")

    if cursor is not None and (not isinstance(cursor, str) or cursor == ""):
        _log("firecrawl_check_batch_status", None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor must be a non-empty string when provided")

    allowed_status = {"queued", "fetching", "scraping", "succeeded", "failed", "skipped"}
    if status is not None:
        if not isinstance(status, list) or any((not isinstance(s, str) or s not in allowed_status) for s in status):
            _log("firecrawl_check_batch_status", None, None, "error", "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "status contains unsupported values", allowed=list(sorted(allowed_status)))

    # ---- load and locate job ----
    jobs = _load("jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    job = next((j for j in jobs if isinstance(j, dict) and j.get("id") == jobId), None)

    # Backwards-compatible behavior for mis-specified ids seen in audit: if jobId isn't found and it looks like a workspace id,
    # return the most recent batch_scrape job in that workspace.
    if job is None and isinstance(jobId, str) and jobId.startswith("fc_wsp_"):
        cand = [j for j in jobs if isinstance(j, dict) and j.get("workspace_id") == jobId and j.get("tool") == "firecrawl_batch_scrape"]
        cand.sort(key=lambda x: x.get("created_at") or "", reverse=True)
        job = cand[0] if cand else None

    if not job:
        _log("firecrawl_check_batch_status", None, None, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "UNKNOWN_JOB: job id does not exist")

    # Must be a batch scrape job
    if job.get("tool") != "firecrawl_batch_scrape":
        # Treat as not found for this endpoint (matches typical API behavior)
        api_key_id = job.get("api_key_id")
        _log("firecrawl_check_batch_status", api_key_id, job.get("workspace_id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "UNKNOWN_JOB: job is not a batch scrape job")

    # ---- ambient auth resolution against the job's workspace ----
    key, ws, api_keys, workspaces = _resolve_auth_for_job(job)
    if not key or not ws:
        _log("firecrawl_check_batch_status", None, job.get("workspace_id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "FORBIDDEN: no active API key for an active workspace can access this job")

    # update last_used_at, workspace usage bucket if needed
    now = _now_iso()
    key["last_used_at"] = now
    key["updated_at"] = key.get("updated_at") or now
    ws = _ensure_month_bucket(ws)

    # persist auth/usage maintenance
    _save("api_keys.json", api_keys)
    _save("workspaces.json", workspaces)

    # ---- compute item aggregates and return items page ----
    job_items = _load("job_items.json")
    if not isinstance(job_items, list):
        job_items = []
    items = [it for it in job_items if isinstance(it, dict) and it.get("job_id") == job.get("id")]

    # filter by status if provided
    if status:
        stset = set(status)
        items = [it for it in items if it.get("status") in stset]

    # stable ordering: by sequence then created_at then id
    def _seq_key(it):
        seq = it.get("sequence")
        try:
            seq = int(seq)
        except Exception:
            seq = 10**18
        return (seq, it.get("created_at") or "", it.get("id") or "")

    items.sort(key=_seq_key)

    # pagination: cursor is last-seen item id
    start = 0
    if cursor:
        for i, it in enumerate(items):
            if it.get("id") == cursor:
                start = i + 1
                break

    page_items = items[start : start + limit]
    next_cursor = page_items[-1].get("id") if (start + limit) < len(items) and page_items else None
    has_more = (start + limit) < len(items)
    total = len(items)

    # aggregates across *all* job items for the job (not filtered)
    all_items = [it for it in job_items if isinstance(it, dict) and it.get("job_id") == job.get("id")]
    counts_by_status = {s: 0 for s in allowed_status}
    counts_by_kind = {}
    for it in all_items:
        st = it.get("status")
        if st in counts_by_status:
            counts_by_status[st] += 1
        kd = it.get("kind")
        if isinstance(kd, str):
            counts_by_kind[kd] = counts_by_kind.get(kd, 0) + 1

    # include pages if requested
    pages_map = {}
    if includePages:
        pages = _load("pages.json")
        if not isinstance(pages, list):
            pages = []
        # Only include pages from same workspace and referenced by returned items
        want_page_ids = {it.get("page_id") for it in page_items if isinstance(it, dict) and it.get("page_id")}
        for p in pages:
            if not isinstance(p, dict):
                continue
            if p.get("id") in want_page_ids and p.get("workspace_id") == job.get("workspace_id"):
                pages_map[p.get("id")] = p

    def _item_out(it):
        out = {
            "id": it.get("id"),
            "sequence": it.get("sequence"),
            "url": it.get("url"),
            "status": it.get("status"),
            "kind": it.get("kind"),
            "http_status": it.get("http_status"),
            "title": it.get("title"),
            "description": it.get("description"),
            "error_message": it.get("error_message"),
            "page_id": it.get("page_id"),
            "created_at": it.get("created_at"),
            "updated_at": it.get("updated_at"),
        }
        if includePages and it.get("page_id") and it.get("page_id") in pages_map:
            out["page"] = pages_map[it.get("page_id")]
        return out

    resp = {
        "job": {
            "id": job.get("id"),
            "tool": job.get("tool"),
            "status": job.get("status"),
            "priority": job.get("priority"),
            "pages_fetched": job.get("pages_fetched"),
            "llm_tokens_used": job.get("llm_tokens_used"),
            "error_code": job.get("error_code"),
            "error_message": job.get("error_message"),
            "result_summary": job.get("result_summary"),
            "created_at": job.get("created_at"),
            "updated_at": job.get("updated_at"),
            "finished_at": job.get("finished_at"),
            "started_at": job.get("started_at"),
        },
        "items": [_item_out(it) for it in page_items],
        "aggregates": {"by_status": counts_by_status, "by_kind": counts_by_kind},
        "pagination": {"total": total, "has_more": has_more, "next_cursor": next_cursor},
    }

    _log("firecrawl_check_batch_status", key.get("id"), ws.get("id"), "ok", None)
    return resp

def firecrawl_check_crawl_status(jobId, includePages=None, limit=None, cursor=None, status=None, **_extra):
