        cand.sort(key=lambda x: x.get("created_at") or "", reverse=True)
        job = cand[0] if cand else None

    if not job:
        _log("firecrawl_check_crawl_status", None, None, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "UNKNOWN_JOB: job id does not exist")

    if job.get("tool") != "firecrawl_crawl":
        _log("firecrawl_check_crawl_status", job.get("api_key_id"), job.get("workspace_id"), "error", "NOT_FOUND")
        return _err("NOT_FOUND", "UNKNOWN_JOB: job is not a crawl job")

    # ---- ambient auth resolution ----
    key, ws, api_keys, workspaces = _resolve_auth_for_job(job)
    if not key or not ws:
        _log("firecrawl_check_crawl_status", None, job.get("workspace_id"), "error", "UNAUTHORIZED")
