    now = _now_iso()
    key["last_used_at"] = now
    key["updated_at"] = key.get("updated_at") or now
    ws = _ensure_month_bucket(ws)
    _save("api_keys.json", api_keys)
    _save("workspaces.json", workspaces)

    # ---- items / aggregates ----
    job_items = _load("job_items.json")
    if not isinstance(job_items, list):
