            out["page"] = pages_map[it.get("page_id")]
        return out

    resp = {
        "job": {
            "id": job.get("id"),
            "tool": job.get("tool"),
            "status": job.get("status"),
            "priority": job.get("priority"),
            "pages_fetched": job.get("pages_fetched"),
            "llm_tokens_used": job.get("llm_tokens_used"),
            "error_code": job.get("error_code"),
            "error_message": job.get("error_message"),
            "result_summary": job.get("result_summary"),
            "created_at": job.get("created_at"),
            "updated_at": job.get("updated_at"),
            "finished_at": job.get("finished_at"),
            "started_at": job.get("started_at"),
        },
        "items": [_item_out(it) for it in page_items],
        "aggregates": {"by_status": counts_by_status, "by_kind": counts_by_kind},
        "pagination": {"total": total, "has_more": has_more, "next_cursor": next_cursor},
    }

    _log("firecrawl_check_crawl_status", key.get("id"), ws.get("id"), "ok", None)
    return resp

def firecrawl_search(query, limit=None, cursor=None, language=None, country=None, scrapeOptions=None, **_extra):
    import json, os, datetime, time, re, base64, hashlib, random, urllib.parse

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0122000" if __import__("os").path.isdir("./environment_mix/0122000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _month_bucket():
        return datetime.datetime.utcnow().strftime("%Y-%m")

    def _log_request(api_key_id, workspace_id, endpoint, status_code, error_code=None):
        try:
            fname = None
            for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage_logs.json"):
                if os.path.exists(os.path.join(_DB, cand)):
                    fname = cand
                    break
            if not fname:
                return
            rows = _load(fname)
            rows.append(
                {
                    "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                    "timestamp": _now(),
                    "endpoint": endpoint,
                    "api_key_id": api_key_id,
                    "workspace_id": workspace_id,
                    "status": status_code,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - _t0) * 1000),
                }
            )
            _save(fname, rows)
        except Exception:
            return

    def _resolve_auth():
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            ws = ws_by_id.get(k.get("workspace_id"))
            if ws and ws.get("status") == "active":
                return k, ws
        return None, None

    def _parse_cursor(cur):
        if cur is None:
            return 0
        if not isinstance(cur, str) or len(cur) > 256:
            return None
        try:
            raw = base64.urlsafe_b64decode(cur.encode("utf-8") + b"===")
            s = raw.decode("utf-8")
            if not s.startswith("offset:"):
                return None
            off = int(s.split(":", 1)[1])
            if off < 0:
                return None
            return off
        except Exception:
            return None

    def _make_cursor(off):
        s = f"offset:{off}".encode("utf-8")
        return base64.urlsafe_b64encode(s).decode("utf-8").rstrip("=")

    def _new_id(prefix):
        return f"{prefix}{hashlib.sha256(f'{time.time_ns()}:{random.random()}'.encode()).hexdigest()[:18]}"

    def _reset_month_if_needed(ws_row):
        mb = _month_bucket()
        if ws_row.get("usage_month") != mb:
            ws_row["usage_month"] = mb
            ws_row["pages_used"] = 0
            ws_row["llm_tokens_used"] = 0

    # Validate inputs
    if not isinstance(query, str) or not query.strip():
        k, ws = _resolve_auth()
        _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_search", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must be a non-empty string")

    if limit is None:
        limit_val = 10
    else:
        if not isinstance(limit, int):
            k, ws = _resolve_auth()
            _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_search", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be an integer")
        if limit <= 0 or limit > 100:
            k, ws = _resolve_auth()
            _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_search", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "limit must be between 1 and 100")
        limit_val = limit

    off = _parse_cursor(cursor)
    if off is None:
        k, ws = _resolve_auth()
        _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_search", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "cursor is invalid")

    if language is not None and not isinstance(language, str):
        k, ws = _resolve_auth()
        _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_search", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "language must be a string")

    if country is not None and not isinstance(country, str):
        k, ws = _resolve_auth()
        _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_search", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "country must be a string")

    if scrapeOptions is not None:
        if not isinstance(scrapeOptions, dict):
            k, ws = _resolve_auth()
            _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_search", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "scrapeOptions must be an object")
        allowed_keys = {"formats", "onlyMainContent", "includeHtml", "includeMarkdown", "includeText", "waitFor", "timeout", "headers", "proxy"}
        for kk in scrapeOptions.keys():
            if kk not in allowed_keys:
                k, ws = _resolve_auth()
                _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_search", 400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"scrapeOptions contains unsupported field '{kk}'")
        if "formats" in scrapeOptions:
            fmts = scrapeOptions["formats"]
            if not isinstance(fmts, list) or any((not isinstance(x, str) or x not in {"html", "text", "markdown"}) for x in fmts):
                k, ws = _resolve_auth()
                _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_search", 400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "scrapeOptions.formats contains unsupported values")
        if "proxy" in scrapeOptions and scrapeOptions["proxy"] is not None and scrapeOptions["proxy"] not in ("none", "auto"):
            k, ws = _resolve_auth()
            _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_search", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "scrapeOptions.proxy must be 'none' or 'auto'")
        if "headers" in scrapeOptions:
            hdrs = scrapeOptions["headers"]
            if not isinstance(hdrs, dict) or any(not isinstance(k, str) or not isinstance(v, str) for k, v in hdrs.items()):
                k, ws = _resolve_auth()
                _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_search", 400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "scrapeOptions.headers must be an object of string:string")
        for int_field in ("waitFor", "timeout"):
            if int_field in scrapeOptions and scrapeOptions[int_field] is not None:
                if not isinstance(scrapeOptions[int_field], int) or scrapeOptions[int_field] < 0:
                    k, ws = _resolve_auth()
                    _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_search", 400, "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"scrapeOptions.{int_field} must be a non-negative integer")
        for b in ("onlyMainContent", "includeHtml", "includeMarkdown", "includeText"):
            if b in scrapeOptions and scrapeOptions[b] is not None and not isinstance(scrapeOptions[b], bool):
                k, ws = _resolve_auth()
                _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_search", 400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"scrapeOptions.{b} must be a boolean")

    api_key, ws = _resolve_auth()
    if not api_key or not ws:
        _log_request(None, None, "firecrawl_search", 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key/workspace available for this request")

    # Load/maybe reset monthly usage bucket
    workspaces = _load("workspaces.json")
    ws_row = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == ws.get("id"):
            ws_row = w
            break
    if not ws_row:
        _log_request(api_key.get("id"), ws.get("id"), "firecrawl_search", 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace context not available")

    _reset_month_if_needed(ws_row)

    # Create job
    jobs = _load("jobs.json")
    job_items = _load("job_items.json")
    pages = _load("pages.json")

    now = _now()
    job_id = "fc_job_" + hashlib.sha256(f"{time.time_ns()}:{random.random()}".encode()).hexdigest()[:18]

    priority = 0
    job_input = {"query": query, "limit": limit_val, "cursor": cursor, "language": language, "country": country}
    if scrapeOptions is not None:
        job_input["scrapeOptions"] = scrapeOptions

    job = {
        "id": job_id,
        "workspace_id": ws_row.get("id"),
        "api_key_id": api_key.get("id"),
        "tool": "firecrawl_search",
        "status": "running",
        "priority": priority,
        "input": job_input,
        "webhook_url": None,
        "webhook_secret": None,
        "started_at": now,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "result_summary": None,
        "pages_fetched": 0,
        "llm_tokens_used": 0,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)

    # Deterministically generate "SERP-like" URLs for offline operation
    # Produce a stable pool of 50 results per query
    q_norm = " ".join(query.strip().split())
    qh = hashlib.sha256(q_norm.encode("utf-8")).hexdigest()
    total_pool = 50
    base_domain = "https://example.com"
    lang_part = (language or "en").lower()
    ctry_part = (country or "us").lower()
    pool = []
    for i in range(total_pool):
        slug = qh[:8] + f"{i:02d}"
        url = f"{base_domain}/search/{urllib.parse.quote(lang_part)}/{urllib.parse.quote(ctry_part)}/{slug}"
        title = f"Result {i+1} for {q_norm}"
        desc = f"Snippet for '{q_norm}' ({lang_part}-{ctry_part}), item {i+1}."
        pool.append((url, title, desc))

    # Page the pool
    sliced = pool[off: off + limit_val]
    has_more = (off + len(sliced)) < len(pool)
    next_cursor = _make_cursor(off + len(sliced)) if has_more else None

    # Decide scraping
    do_scrape = scrapeOptions is not None
    formats = None
    if do_scrape:
        formats = scrapeOptions.get("formats") if isinstance(scrapeOptions, dict) else None
        if not formats:
            # infer from include flags or default to text+markdown
            inc_html = bool(scrapeOptions.get("includeHtml")) if isinstance(scrapeOptions, dict) else False
            inc_text = bool(scrapeOptions.get("includeText")) if isinstance(scrapeOptions, dict) else True
            inc_md = bool(scrapeOptions.get("includeMarkdown")) if isinstance(scrapeOptions, dict) else True
            formats = []
            if inc_html:
                formats.append("html")
            if inc_text:
                formats.append("text")
            if inc_md:
                formats.append("markdown")
            if not formats:
                formats = ["text"]

    # Quota check: if scraping, count pages to be fetched = number of sliced results
    pages_to_fetch = len(sliced) if do_scrape else 0
    projected_pages = int(ws_row.get("pages_used") or 0) + pages_to_fetch
    if pages_to_fetch > 0 and projected_pages > int(ws_row.get("monthly_page_limit") or 0):
        # Fail job due to quota
        job["status"] = "failed"
        job["finished_at"] = now
        job["updated_at"] = now
        job["error_code"] = "quota_exceeded"
        job["error_message"] = "Monthly page limit exceeded"
        job["result_summary"] = {"webhook": {"attempted_at": None, "status_code": None, "error": None}}
        _save("jobs.json", jobs)
        _save("workspaces.json", workspaces)
        # Update last_used_at
        api_keys = _load("api_keys.json")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)
        _log_request(api_key.get("id"), ws_row.get("id"), "firecrawl_search", 429, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Monthly page quota exceeded", jobId=job_id)

    # Create items and optional pages
    seq0 = 0
    created_items = []
    created_pages = 0
    for idx, (url, title, desc) in enumerate(sliced):
        item_id = _new_id("fci_")
        it = {
            "id": item_id,
            "job_id": job_id,
            "sequence": seq0 + idx,
            "url": url,
            "parent_url": None,
            "depth": None,
            "kind": "serp_result",
            "status": "succeeded",
            "http_status": 200 if do_scrape else None,
            "title": title,
            "description": desc,
            "page_id": None,
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }

        if do_scrape:
            # Create stored page artifact
            page_id = _new_id("fcp_")
            text = f"{title}\n\n{desc}\n\nQuery: {q_norm}\nURL: {url}\n"
            md = f"# {title}\n\n{desc}\n\n- Query: {q_norm}\n- URL: {url}\n"
            html = f"<html><head><title>{title}</title></head><body><h1>{title}</h1><p>{desc}</p></body></html>"
            # Only include requested formats (others None)
            html_out = html if "html" in formats else None
            text_out = text if "text" in formats else None
            md_out = md if "markdown" in formats else None
            content_for_hash = (text_out or md_out or "") + (title or "")
            sha = hashlib.sha256(content_for_hash.encode("utf-8")).hexdigest()

            # Uniqueness constraint: unique(workspace_id, url, content_sha256) where content_sha256 not null
            dup = False
            for p in pages:
                if isinstance(p, dict) and p.get("workspace_id") == ws_row.get("id") and p.get("url") == url and p.get("content_sha256") == sha:
                    it["page_id"] = p.get("id")
                    dup = True
                    break
            if not dup:
                p = {
                    "id": page_id,
                    "workspace_id": ws_row.get("id"),
                    "source_job_id": job_id,
                    "url": url,
                    "fetched_url": url,
                    "status": "stored",
                    "content_type": "text/html",
                    "language": language,
                    "title": title,
                    "html": html_out,
                    "text": text_out,
                    "markdown": md_out,
                    "metadata": {"search": {"query": q_norm, "rank": off + idx + 1, "language": language, "country": country}},
                    "extracted_data": None,
                    "llms_txt": None,
                    "content_sha256": sha,
                    "created_at": now,
                    "updated_at": now,
                }
                pages.append(p)
                it["page_id"] = page_id
                created_pages += 1

        job_items.append(it)
        created_items.append(it)

    # Complete job
    job["status"] = "succeeded"
    job["finished_at"] = _now()
    job["updated_at"] = job["finished_at"]
    job["pages_fetched"] = int(created_pages)
    job["result_summary"] = {
        "results_returned": len(created_items),
        "total_available_estimate": len(pool),
        "webhook": {"attempted_at": None, "status_code": None, "error": None},
    }

    # Quota accounting on completion
    ws_row["pages_used"] = int(ws_row.get("pages_used") or 0) + int(job["pages_fetched"] or 0)
    ws_row["llm_tokens_used"] = int(ws_row.get("llm_tokens_used") or 0) + int(job["llm_tokens_used"] or 0)
    ws_row["updated_at"] = job["updated_at"]

    # Persist
    _save("jobs.json", jobs)
    _save("job_items.json", job_items)
    _save("pages.json", pages)
    _save("workspaces.json", workspaces)

    # Update last_used_at
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = job["updated_at"]
            k["updated_at"] = job["updated_at"]
            break
    _save("api_keys.json", api_keys)

    # Response: return items (and page content if scraped)
    pages_by_id = {p.get("id"): p for p in pages if isinstance(p, dict) and p.get("workspace_id") == ws_row.get("id")}

    out_items = []
    for it in created_items:
        row = {"url": it.get("url"), "title": it.get("title"), "description": it.get("description")}
        if do_scrape:
            pid = it.get("page_id")
            if pid and pid in pages_by_id:
                p = pages_by_id[pid]
                row["pageId"] = pid
                row["content"] = {
                    "url": p.get("url"),
                    "html": p.get("html"),
                    "text": p.get("text"),
                    "markdown": p.get("markdown"),
                    "metadata": p.get("metadata"),
                }
        out_items.append(row)

    resp = {
        "jobId": job_id,
        "status": job["status"],
        "results": out_items,
        "pagination": {"limit": limit_val, "cursor": cursor, "next_cursor": next_cursor, "has_more": has_more},
    }

    _log_request(api_key.get("id"), ws_row.get("id"), "firecrawl_search", 200, None)
    return resp

def firecrawl_extract(urls, schema, prompt=None, provider=None, model=None, webhook=None, webhookSecret=None, priority=None, scrapeOptions=None, **_extra):
    import json, os, datetime, time, re, hashlib, random, urllib.parse

    _t0 = time.time()
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0122000" if __import__("os").path.isdir("./environment_mix/0122000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _month_bucket():
        return datetime.datetime.utcnow().strftime("%Y-%m")

    def _log_request(api_key_id, workspace_id, endpoint, status_code, error_code=None):
        try:
            fname = None
            for cand in ("request_logs.json", "requests.json", "audit_logs.json", "usage_logs.json"):
                if os.path.exists(os.path.join(_DB, cand)):
                    fname = cand
                    break
            if not fname:
                return
            rows = _load(fname)
            rows.append(
                {
                    "id": f"req_{int(time.time()*1000)}_{os.getpid()}",
                    "timestamp": _now(),
                    "endpoint": endpoint,
                    "api_key_id": api_key_id,
                    "workspace_id": workspace_id,
                    "status": status_code,
                    "error_code": error_code,
                    "latency_ms": int((time.time() - _t0) * 1000),
                }
            )
            _save(fname, rows)
        except Exception:
            return

    def _resolve_auth():
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            ws = ws_by_id.get(k.get("workspace_id"))
            if ws and ws.get("status") == "active":
                return k, ws
        return None, None

    def _new_id(prefix):
        return f"{prefix}{hashlib.sha256(f'{time.time_ns()}:{random.random()}'.encode()).hexdigest()[:18]}"

    def _reset_month_if_needed(ws_row):
        mb = _month_bucket()
        if ws_row.get("usage_month") != mb:
            ws_row["usage_month"] = mb
            ws_row["pages_used"] = 0
            ws_row["llm_tokens_used"] = 0

    def _validate_url(u):
        if not isinstance(u, str):
            return False
        return bool(re.match(r"^https?://", u))

    # Validate inputs
    if not isinstance(urls, list) or len(urls) == 0 or any(not _validate_url(u) for u in urls):
        k, ws = _resolve_auth()
        _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_extract", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "urls must be a non-empty array of absolute http(s) URLs")

    if not isinstance(schema, dict):
        k, ws = _resolve_auth()
        _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_extract", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "schema must be an object")

    if prompt is not None and not isinstance(prompt, str):
        k, ws = _resolve_auth()
        _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_extract", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "prompt must be a string")

    if provider is not None and provider not in ("cloud", "self_hosted"):
        k, ws = _resolve_auth()
        _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_extract", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "provider must be 'cloud' or 'self_hosted'")

    if model is not None and not isinstance(model, str):
        k, ws = _resolve_auth()
        _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_extract", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "model must be a string")

    if webhook is not None:
        if not isinstance(webhook, str) or not re.match(r"^https?://", webhook):
            k, ws = _resolve_auth()
            _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_extract", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "webhook must be an http(s) URL")

    if webhookSecret is not None and not isinstance(webhookSecret, str):
        k, ws = _resolve_auth()
        _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_extract", 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "webhookSecret must be a string")

    if priority is None:
        prio = 0
    else:
        if not isinstance(priority, int):
            k, ws = _resolve_auth()
            _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_extract", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "priority must be an integer")
        if priority < -10 or priority > 10:
            k, ws = _resolve_auth()
            _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_extract", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "priority must be between -10 and 10")
        prio = priority

    if scrapeOptions is not None:
        if not isinstance(scrapeOptions, dict):
            k, ws = _resolve_auth()
            _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_extract", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "scrapeOptions must be an object")
        allowed_keys = {"formats", "onlyMainContent", "includeHtml", "includeMarkdown", "includeText", "waitFor", "timeout", "headers", "proxy"}
        for kk in scrapeOptions.keys():
            if kk not in allowed_keys:
                k, ws = _resolve_auth()
                _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_extract", 400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"scrapeOptions contains unsupported field '{kk}'")
        if "formats" in scrapeOptions:
            fmts = scrapeOptions["formats"]
            if not isinstance(fmts, list) or any((not isinstance(x, str) or x not in {"html", "text", "markdown"}) for x in fmts):
                k, ws = _resolve_auth()
                _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_extract", 400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "scrapeOptions.formats contains unsupported values")
        if "proxy" in scrapeOptions and scrapeOptions["proxy"] is not None and scrapeOptions["proxy"] not in ("none", "auto"):
            k, ws = _resolve_auth()
            _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_extract", 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "scrapeOptions.proxy must be 'none' or 'auto'")
        if "headers" in scrapeOptions:
            hdrs = scrapeOptions["headers"]
            if not isinstance(hdrs, dict) or any(not isinstance(k, str) or not isinstance(v, str) for k, v in hdrs.items()):
                k, ws = _resolve_auth()
                _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_extract", 400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "scrapeOptions.headers must be an object of string:string")
        for int_field in ("waitFor", "timeout"):
            if int_field in scrapeOptions and scrapeOptions[int_field] is not None:
                if not isinstance(scrapeOptions[int_field], int) or scrapeOptions[int_field] < 0:
                    k, ws = _resolve_auth()
                    _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_extract", 400, "VALIDATION_ERROR")
                    return _err("VALIDATION_ERROR", f"scrapeOptions.{int_field} must be a non-negative integer")
        for b in ("onlyMainContent", "includeHtml", "includeMarkdown", "includeText"):
            if b in scrapeOptions and scrapeOptions[b] is not None and not isinstance(scrapeOptions[b], bool):
                k, ws = _resolve_auth()
                _log_request(k.get("id") if k else None, ws.get("id") if ws else None, "firecrawl_extract", 400, "VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", f"scrapeOptions.{b} must be a boolean")

    api_key, ws = _resolve_auth()
    if not api_key or not ws:
        _log_request(None, None, "firecrawl_extract", 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key/workspace available for this request")

    # Load workspace row to manage quota bucket
    workspaces = _load("workspaces.json")
    ws_row = None
    for w in workspaces:
        if isinstance(w, dict) and w.get("id") == ws.get("id"):
            ws_row = w
            break
    if not ws_row:
        _log_request(api_key.get("id"), ws.get("id"), "firecrawl_extract", 401, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "Workspace context not available")

    _reset_month_if_needed(ws_row)

    jobs = _load("jobs.json")
    job_items = _load("job_items.json")
    pages = _load("pages.json")

    now = _now()
    job_id = "fc_job_" + hashlib.sha256(f"{time.time_ns()}:{random.random()}".encode()).hexdigest()[:18]

    # Estimate LLM token usage (offline heuristic): ~200 tokens per URL + schema size
    schema_size = len(json.dumps(schema, ensure_ascii=False))
    est_tokens = max(1, int((schema_size / 4)))  # rough chars->tokens
    est_tokens = min(4000, est_tokens)
    llm_tokens = len(urls) * 200 + est_tokens + (len(prompt) // 4 if isinstance(prompt, str) else 0)

    projected_tokens = int(ws_row.get("llm_tokens_used") or 0) + int(llm_tokens)
    if projected_tokens > int(ws_row.get("monthly_llm_token_limit") or 0):
        # Create failed job due to quota (rule allows reject or forced failed job)
        job = {
            "id": job_id,
            "workspace_id": ws_row.get("id"),
            "api_key_id": api_key.get("id"),
            "tool": "firecrawl_extract",
            "status": "failed",
            "priority": prio,
            "input": {
                "urls": urls,
                "schema": schema,
                "prompt": prompt,
                "provider": provider,
                "model": model,
                "scrapeOptions": scrapeOptions,
            },
            "webhook_url": webhook,
            "webhook_secret": webhookSecret,
            "started_at": now,
            "finished_at": now,
            "error_code": "quota_exceeded",
            "error_message": "Monthly LLM token limit exceeded",
            "result_summary": {"webhook": {"attempted_at": None, "status_code": None, "error": None}},
            "pages_fetched": 0,
            "llm_tokens_used": 0,
            "created_at": now,
            "updated_at": now,
        }
        jobs.append(job)
        _save("jobs.json", jobs)
        _save("workspaces.json", workspaces)

        api_keys = _load("api_keys.json")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)

        _log_request(api_key.get("id"), ws_row.get("id"), "firecrawl_extract", 429, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Monthly LLM token quota exceeded", jobId=job_id)

    # If scrapeOptions provided, we will "fetch" the pages before extraction, consuming page quota.
    do_scrape = scrapeOptions is not None
    pages_to_fetch = len(urls) if do_scrape else 0
    projected_pages = int(ws_row.get("pages_used") or 0) + pages_to_fetch
    if do_scrape and projected_pages > int(ws_row.get("monthly_page_limit") or 0):
        job = {
            "id": job_id,
            "workspace_id": ws_row.get("id"),
            "api_key_id": api_key.get("id"),
            "tool": "firecrawl_extract",
            "status": "failed",
            "priority": prio,
            "input": {
                "urls": urls,
                "schema": schema,
                "prompt": prompt,
                "provider": provider,
                "model": model,
                "scrapeOptions": scrapeOptions,
            },
            "webhook_url": webhook,
            "webhook_secret": webhookSecret,
            "started_at": now,
            "finished_at": now,
            "error_code": "quota_exceeded",
            "error_message": "Monthly page limit exceeded",
            "result_summary": {"webhook": {"attempted_at": None, "status_code": None, "error": None}},
            "pages_fetched": 0,
            "llm_tokens_used": 0,
            "created_at": now,
            "updated_at": now,
        }
        jobs.append(job)
        _save("jobs.json", jobs)
        _save("workspaces.json", workspaces)
        api_keys = _load("api_keys.json")
        for k in api_keys:
            if isinstance(k, dict) and k.get("id") == api_key.get("id"):
                k["last_used_at"] = now
                k["updated_at"] = now
                break
        _save("api_keys.json", api_keys)
        _log_request(api_key.get("id"), ws_row.get("id"), "firecrawl_extract", 429, "QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Monthly page quota exceeded", jobId=job_id)

    job = {
        "id": job_id,
        "workspace_id": ws_row.get("id"),
        "api_key_id": api_key.get("id"),
        "tool": "firecrawl_extract",
        "status": "running",
        "priority": prio,
        "input": {
            "urls": urls,
            "schema": schema,
            "prompt": prompt,
            "provider": provider,
            "model": model,
            "scrapeOptions": scrapeOptions,
        },
        "webhook_url": webhook,
        "webhook_secret": webhookSecret,
        "started_at": now,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "result_summary": None,
        "pages_fetched": 0,
        "llm_tokens_used": 0,
        "created_at": now,
        "updated_at": now,
    }
    jobs.append(job)

    # Create job_items for URLs and ensure pages exist in workspace
    formats = None
    if do_scrape:
        formats = scrapeOptions.get("formats") if isinstance(scrapeOptions, dict) else None
        if not formats:
            inc_html = bool(scrapeOptions.get("includeHtml")) if isinstance(scrapeOptions, dict) else False
            inc_text = bool(scrapeOptions.get("includeText")) if isinstance(scrapeOptions, dict) else True
            inc_md = bool(scrapeOptions.get("includeMarkdown")) if isinstance(scrapeOptions, dict) else True
            formats = []
            if inc_html:
                formats.append("html")
            if inc_text:
                formats.append("text")
            if inc_md:
                formats.append("markdown")
            if not formats:
                formats = ["text"]

    pages_by_url = {}
    for p in pages:
        if isinstance(p, dict) and p.get("workspace_id") == ws_row.get("id") and isinstance(p.get("url"), str):
            pages_by_url.setdefault(p["url"], []).append(p)

    created_pages = 0
    extracted_pages = []
    for i, u in enumerate(urls):
        item_id = _new_id("fci_")
        page_id = None

        # Find existing stored page for URL (any content_sha256)
        existing = None
        for cand in pages_by_url.get(u, []):
            if cand.get("status") == "stored":
                existing = cand
                break

        if existing:
            page_id = existing.get("id")
        else:
            # If scrapeOptions absent, still need a page to store extracted_data:
            # Create minimal page artifact.
            pid = _new_id("fcp_")
            title = urllib.parse.urlparse(u).netloc
            text = f"Content placeholder for {u}"
            md = f"# {title}\n\n{u}\n"
            html = f"<html><head><title>{title}</title></head><body><p>{u}</p></body></html>"
            html_out = html if (do_scrape and "html" in formats) else None
            text_out = text if ((do_scrape and "text" in formats) or (not do_scrape)) else None
            md_out = md if (do_scrape and "markdown" in formats) else None
            content_for_hash = (text_out or md_out or "") + (title or "")
            sha = hashlib.sha256(content_for_hash.encode("utf-8")).hexdigest()

            p = {
                "id": pid,
                "workspace_id": ws_row.get("id"),
                "source_job_id": job_id,
                "url": u,
                "fetched_url": u,
                "status": "stored",
                "content_type": "text/html" if html_out else None,
                "language": None,
                "title": title,
                "html": html_out,
                "text": text_out,
                "markdown": md_out,
                "metadata": {"extraction": {"created_for_extraction": True, "scraped": bool(do_scrape)}},
                "extracted_data": None,
                "llms_txt": None,
                "content_sha256": sha,
                "created_at": now,
                "updated_at": now,
            }
            pages.append(p)
            pages_by_url.setdefault(u, []).append(p)
            page_id = pid
            created_pages += 1

        it = {
            "id": item_id,
            "job_id": job_id,
            "sequence": i,
            "url": u,
            "parent_url": None,
            "depth": None,
            "kind": "batch_target",
            "status": "succeeded",
            "http_status": 200 if do_scrape else None,
            "title": None,
            "description": None,
            "page_id": page_id,
            "error_message": None,
            "created_at": now,
            "updated_at": now,
        }
        job_items.append(it)
        extracted_pages.append(page_id)

    # Write extracted_data into pages for corresponding page(s)
    # Offline extraction: produce a deterministic structure using schema keys.
    def _extract_for_url(u):
        base = {
            "_meta": {
                "url": u,
                "provider": provider or "cloud",
                "model": model,
                "prompt": prompt,
                "generated_at": _now(),
            }
        }
        # If schema has "properties", create keys with placeholder values
        props = schema.get("properties") if isinstance(schema, dict) else None
        if isinstance(props, dict):
            for k in props.keys():
                base[k] = f"extracted:{k}"
        else:
            base["data"] = "extracted"
        return base

    pages_by_id = {p.get("id"): p for p in pages if isinstance(p, dict) and p.get("workspace_id") == ws_row.get("id")}
    for u, pid in zip(urls, extracted_pages):
        p = pages_by_id.get(pid)
        if p and p.get("status") == "stored":
            p["extracted_data"] = _extract_for_url(u)
            p["updated_at"] = _now()

    # Complete job and quota accounting
    job["status"] = "succeeded"
    job["finished_at"] = _now()
    job["updated_at"] = job["finished_at"]
    job["pages_fetched"] = int(created_pages if do_scrape else 0)
    job["llm_tokens_used"] = int(llm_tokens)
    job["result_summary"] = {
        "urls_processed": len(urls),
        "pages_created": created_pages,
        "webhook": {"attempted_at": None, "status_code": None, "error": None},
    }

    ws_row["pages_used"] = int(ws_row.get("pages_used") or 0) + int(job["pages_fetched"] or 0)
    ws_row["llm_tokens_used"] = int(ws_row.get("llm_tokens_used") or 0) + int(job["llm_tokens_used"] or 0)
    ws_row["updated_at"] = job["updated_at"]

    # Webhook delivery attempt exactly once on terminal completion
    if webhook:
        # Offline: attempt and record without changing terminal status.
        attempted_at = _now()
        # No actual network call; record as attempted with error.
        job["result_summary"]["webhook"] = {
            "attempted_at": attempted_at,
            "status_code": None,
            "error": "offline_no_network",
        }

    # Persist
    _save("pages.json", pages)
    _save("job_items.json", job_items)
    _save("jobs.json", jobs)
    _save("workspaces.json", workspaces)

    # Update last_used_at
    api_keys = _load("api_keys.json")
    for k in api_keys:
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            k["last_used_at"] = job["updated_at"]
            k["updated_at"] = job["updated_at"]
            break
    _save("api_keys.json", api_keys)

    # Build response: include per-url extracted data pointers + small outputs
    pages_by_id = {p.get("id"): p for p in pages if isinstance(p, dict) and p.get("workspace_id") == ws_row.get("id")}
    results = []
    for u, pid in zip(urls, extracted_pages):
        p = pages_by_id.get(pid)
        results.append(
            {
                "url": u,
                "pageId": pid,
                "extractedData": (p.get("extracted_data") if p else None),
            }
        )

    resp = {
        "jobId": job_id,
        "status": job["status"],
        "results": results,
        "usage": {"llmTokensUsed": job["llm_tokens_used"], "pagesFetched": job["pages_fetched"]},
    }

    _log_request(api_key.get("id"), ws_row.get("id"), "firecrawl_extract", 200, None)
    return resp

def firecrawl_deep_research(query, workspace_id=None, webhook_url=None, webhook_secret=None, priority=None, max_pages=None, language=None, include_urls=None, exclude_urls=None, output_format=None, **_extra):
    import json, os, datetime, time, re, hashlib, uuid, random, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0122000" if __import__("os").path.isdir("./environment_mix/0122000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    # Load collections
    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    jobs = _load("jobs.json")
    job_items = _load("job_items.json")
    pages = _load("pages.json")
    request_logs = _load("request_logs.json")  # may not exist in schema; safe via _load

    def _log(status, api_key_id=None, workspace_id_log=None, error_code=None):
        nonlocal request_logs
        # "OBSERVABLE SERVICE DYNAMICS": record every call if a log collection exists
        if not isinstance(request_logs, list):
            request_logs = []
        if len(request_logs) > 0 or os.path.exists(os.path.join(_DB, "request_logs.json")):
            request_logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "firecrawl_deep_research",
                "timestamp": now,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "api_key_id": api_key_id,
                "workspace_id": workspace_id_log,
                "error_code": error_code
            })
            _save("request_logs.json", request_logs)

    def _pick_auth_workspace():
        # Ambient authentication: find any active api_key whose workspace is active,
        # preferring requested workspace_id if provided.
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
        candidates = []
        for k in api_keys:
            if not isinstance(k, dict): 
                continue
            if k.get("status") != "active":
                continue
            wid = k.get("workspace_id")
            ws = ws_by_id.get(wid)
            if not ws or ws.get("status") != "active":
                continue
            if workspace_id is not None and wid != workspace_id:
                continue
            candidates.append((k, ws))
        if not candidates and workspace_id is not None:
            # If workspace_id specified but none match, still may be unauthorized
            return None, None
        if not candidates:
            # try any active
            for k in api_keys:
                if not isinstance(k, dict): 
                    continue
                if k.get("status") != "active":
                    continue
                ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
                if ws and ws.get("status") == "active":
                    candidates.append((k, ws))
            if not candidates:
                return None, None
        return candidates[0][0], candidates[0][1]

    def _validate_url(u):
        if not isinstance(u, str) or not re.match(r"^https?://", u):
            return False
        return True

    # Validate inputs
    if not isinstance(query, str) or not query.strip():
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "query must be a non-empty string")
    if workspace_id is not None:
        if not isinstance(workspace_id, str) or not re.match(r"^fc_wsp_[A-Za-z0-9]+$", workspace_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspace_id must match ^fc_wsp_[A-Za-z0-9]+$")
    if webhook_url is not None:
        if not isinstance(webhook_url, str) or not re.match(r"^https?://", webhook_url):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "webhook_url must be a valid http(s) URL")
    if webhook_secret is not None and not isinstance(webhook_secret, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "webhook_secret must be a string")
    if priority is not None:
        if not isinstance(priority, int):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "priority must be an integer")
        if priority < -10 or priority > 10:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "priority must be between -10 and 10")
    if max_pages is not None:
        if not isinstance(max_pages, int) or max_pages <= 0:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "max_pages must be a positive integer")
    if language is not None and not isinstance(language, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "language must be a string")
    if include_urls is not None:
        if not isinstance(include_urls, list) or any(not isinstance(u, str) for u in include_urls):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "include_urls must be an array of strings")
        for u in include_urls:
            if not _validate_url(u):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "include_urls entries must be valid http(s) URLs", url=u)
    if exclude_urls is not None:
        if not isinstance(exclude_urls, list) or any(not isinstance(u, str) for u in exclude_urls):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "exclude_urls must be an array of strings")
        for u in exclude_urls:
            if not _validate_url(u):
                _log("error", error_code="VALIDATION_ERROR")
                return _err("VALIDATION_ERROR", "exclude_urls entries must be valid http(s) URLs", url=u)
    if output_format is not None:
        if output_format not in ("markdown", "text", "json"):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "output_format must be one of: markdown, text, json")

    api_key, ws = _pick_auth_workspace()
    if not api_key or not ws:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key + active workspace available for this request")

    # Reset month bucket if needed (best-effort, per schema)
    def _current_usage_month():
        dt = datetime.datetime.utcnow()
        return f"{dt.year:04d}-{dt.month:02d}"

    cur_month = _current_usage_month()
    if ws.get("usage_month") != cur_month:
        ws["usage_month"] = cur_month
        ws["pages_used"] = 0
        ws["llm_tokens_used"] = 0
        ws["updated_at"] = now
        for i, w in enumerate(workspaces):
            if isinstance(w, dict) and w.get("id") == ws.get("id"):
                workspaces[i] = ws
                break
        _save("workspaces.json", workspaces)

    # Build job input
    inp = {
        "query": query,
        "max_pages": max_pages,
        "language": language,
        "include_urls": include_urls,
        "exclude_urls": exclude_urls,
        "output_format": output_format or "markdown"
    }

    # Create job
    job_id = "fc_job_" + uuid.uuid4().hex
    pr = priority if priority is not None else 0
    job = {
        "id": job_id,
        "workspace_id": ws["id"],
        "api_key_id": api_key.get("id"),
        "tool": "firecrawl_deep_research",
        "status": "queued",
        "priority": pr,
        "input": inp,
        "webhook_url": webhook_url,
        "webhook_secret": webhook_secret,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "result_summary": None,
        "pages_fetched": 0,
        "llm_tokens_used": 0,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)

    # Update api key last_used_at on successful authenticated request creation
    api_key["last_used_at"] = now
    api_key["updated_at"] = now
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            api_keys[i] = api_key
            break

    # Synchronous lightweight completion simulation:
    # create a few research_source items and pages, and a summary. Enforce quotas preflight.
    maxp = max_pages if max_pages is not None else 3
    maxp = max(1, min(maxp, 10))  # keep bounded for offline datastore
    seed_urls = (include_urls or [])[:maxp]
    if not seed_urls:
        q = urllib.parse.quote(query.strip()[:60])
        seed_urls = [f"https://example.com/search?q={q}", f"https://example.org/{q}"][:maxp]

    # Apply exclude filter
    if exclude_urls:
        seed_urls = [u for u in seed_urls if u not in set(exclude_urls)]
        if not seed_urls:
            seed_urls = [f"https://example.com/search?q={urllib.parse.quote(query.strip()[:60])}"]

    # Estimate usage
    est_pages = len(seed_urls)
    # token estimate proportional to query and pages
    est_tokens = max(200, min(8000, 200 * est_pages + 5 * len(query)))

    would_pages = int(ws.get("pages_used", 0)) + est_pages
    would_tokens = int(ws.get("llm_tokens_used", 0)) + est_tokens
    if would_pages > int(ws.get("monthly_page_limit", 0)) or would_tokens > int(ws.get("monthly_llm_token_limit", 0)):
        # force failed job with quota_exceeded, without consuming usage counters
        job["status"] = "failed"
        job["started_at"] = now
        job["finished_at"] = now
        job["error_code"] = "quota_exceeded"
        job["error_message"] = "Monthly quota exceeded"
        job["result_summary"] = {"quota": {"pages_would_be": would_pages, "tokens_would_be": would_tokens}}
        job["updated_at"] = now
        # attempt webhook exactly once for terminal completion
        if webhook_url:
            rs = job.get("result_summary") or {}
            rs["webhook"] = {"attempted_at": now, "status_code": 0, "error": "delivery_not_available_offline"}
            job["result_summary"] = rs
        for i, j in enumerate(jobs):
            if isinstance(j, dict) and j.get("id") == job_id:
                jobs[i] = job
                break
        _save("jobs.json", jobs)
        _save("api_keys.json", api_keys)
        _log("error", api_key_id=api_key.get("id"), workspace_id_log=ws.get("id"), error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Monthly quota exceeded", job_id=job_id)

    # Run through running->succeeded
    job["status"] = "running"
    job["started_at"] = now
    job["updated_at"] = now

    # Create pages + job_items(kind=research_source)
    created_page_ids = []
    seq_base = max([ji.get("sequence", -1) for ji in job_items if isinstance(ji, dict) and ji.get("job_id") == job_id] + [-1]) + 1
    for idx, u in enumerate(seed_urls):
        pid = "fc_page_" + uuid.uuid4().hex
        h = hashlib.sha256((query + "|" + u).encode("utf-8")).hexdigest()
        page = {
            "id": pid,
            "workspace_id": ws["id"],
            "source_job_id": job_id,
            "url": u,
            "fetched_url": u,
            "status": "stored",
            "content_type": "text/html",
            "language": language or "en",
            "title": f"Source {idx+1} for: {query[:60]}",
            "html": None,
            "text": f"Notes extracted from {u} about '{query}'.",
            "markdown": f"# Notes\n\n- Query: {query}\n- Source: {u}\n",
            "metadata": {"generated": True, "source_kind": "research_source"},
            "extracted_data": None,
            "llms_txt": None,
            "content_sha256": h,
            "created_at": now,
            "updated_at": now
        }
        pages.append(page)
        created_page_ids.append(pid)

        ji = {
            "id": "fc_itm_" + uuid.uuid4().hex,
            "job_id": job_id,
            "sequence": seq_base + idx,
            "url": u,
            "parent_url": None,
            "depth": None,
            "kind": "research_source",
            "status": "succeeded",
            "http_status": 200,
            "title": page["title"],
            "description": None,
            "page_id": pid,
            "error_message": None,
            "created_at": now,
            "updated_at": now
        }
        job_items.append(ji)

    # Final summary
    if (output_format or "markdown") == "json":
        findings = {"query": query, "sources": seed_urls, "key_points": ["Offline synthesized summary placeholder."]}
    elif (output_format or "markdown") == "text":
        findings = f"Research Summary\nQuery: {query}\nSources:\n" + "\n".join(f"- {u}" for u in seed_urls) + "\n\nKey points:\n- Offline synthesized summary placeholder.\n"
    else:
        findings = f"# Research Summary\n\n**Query:** {query}\n\n## Sources\n" + "\n".join(f"- {u}" for u in seed_urls) + "\n\n## Key points\n- Offline synthesized summary placeholder.\n"

    job["status"] = "succeeded"
    job["finished_at"] = now
    job["pages_fetched"] = est_pages
    job["llm_tokens_used"] = est_tokens
    job["result_summary"] = {
        "output_format": output_format or "markdown",
        "findings": findings,
        "sources_count": len(seed_urls),
        "page_ids": created_page_ids[:10]
    }

    # Attempt webhook exactly once on terminal completion
    if webhook_url:
        rs = job.get("result_summary") or {}
        rs["webhook"] = {"attempted_at": now, "status_code": 0, "error": "delivery_not_available_offline"}
        job["result_summary"] = rs

    job["updated_at"] = now

    # Persist job and artifacts
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("id") == job_id:
            jobs[i] = job
            break
    _save("jobs.json", jobs)
    _save("job_items.json", job_items)
    _save("pages.json", pages)
    _save("api_keys.json", api_keys)

    # Quota accounting on job completion
    ws["pages_used"] = int(ws.get("pages_used", 0)) + int(job["pages_fetched"])
    ws["llm_tokens_used"] = int(ws.get("llm_tokens_used", 0)) + int(job["llm_tokens_used"])
    ws["updated_at"] = now
    for i, w in enumerate(workspaces):
        if isinstance(w, dict) and w.get("id") == ws.get("id"):
            workspaces[i] = ws
            break
    _save("workspaces.json", workspaces)

    _log("success", api_key_id=api_key.get("id"), workspace_id_log=ws.get("id"))
    return {
        "job": job,
        "result": job.get("result_summary")
    }

def firecrawl_generate_llmstxt(url, workspace_id=None, webhook_url=None, webhook_secret=None, priority=None, max_pages=None, respect_robots_txt=None, output_format=None, **_extra):
    import json, os, datetime, time, re, uuid, urllib.parse
    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0122000" if __import__("os").path.isdir("./environment_mix/0122000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    workspaces = _load("workspaces.json")
    api_keys = _load("api_keys.json")
    jobs = _load("jobs.json")
    pages = _load("pages.json")
    request_logs = _load("request_logs.json")

    def _log(status, api_key_id=None, workspace_id_log=None, error_code=None):
        nonlocal request_logs
        if not isinstance(request_logs, list):
            request_logs = []
        if len(request_logs) > 0 or os.path.exists(os.path.join(_DB, "request_logs.json")):
            request_logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": "firecrawl_generate_llmstxt",
                "timestamp": now,
                "status": status,
                "latency_ms": int((time.time() - t0) * 1000),
                "api_key_id": api_key_id,
                "workspace_id": workspace_id_log,
                "error_code": error_code
            })
            _save("request_logs.json", request_logs)

    def _pick_auth_workspace():
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
        candidates = []
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            wid = k.get("workspace_id")
            ws = ws_by_id.get(wid)
            if not ws or ws.get("status") != "active":
                continue
            if workspace_id is not None and wid != workspace_id:
                continue
            candidates.append((k, ws))
        if not candidates and workspace_id is not None:
            return None, None
        if not candidates:
            for k in api_keys:
                if not isinstance(k, dict):
                    continue
                if k.get("status") != "active":
                    continue
                ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == k.get("workspace_id")), None)
                if ws and ws.get("status") == "active":
                    candidates.append((k, ws))
            if not candidates:
                return None, None
        return candidates[0][0], candidates[0][1]

    # Validate inputs
    if not isinstance(url, str) or not re.match(r"^https?://", url):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "url must be a valid http(s) URL")
    if workspace_id is not None:
        if not isinstance(workspace_id, str) or not re.match(r"^fc_wsp_[A-Za-z0-9]+$", workspace_id):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "workspace_id must match ^fc_wsp_[A-Za-z0-9]+$")
    if webhook_url is not None:
        if not isinstance(webhook_url, str) or not re.match(r"^https?://", webhook_url):
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "webhook_url must be a valid http(s) URL")
    if webhook_secret is not None and not isinstance(webhook_secret, str):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "webhook_secret must be a string")
    if priority is not None:
        if not isinstance(priority, int) or priority < -10 or priority > 10:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "priority must be an integer between -10 and 10")
    if max_pages is not None:
        if not isinstance(max_pages, int) or max_pages <= 0:
            _log("error", error_code="VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "max_pages must be a positive integer")
    if respect_robots_txt is not None and not isinstance(respect_robots_txt, bool):
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "respect_robots_txt must be a boolean")
    if output_format is not None and output_format != "text":
        _log("error", error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "output_format must be 'text' when provided")

    api_key, ws = _pick_auth_workspace()
    if not api_key or not ws:
        _log("error", error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "No active API key + active workspace available for this request")

    def _current_usage_month():
        dt = datetime.datetime.utcnow()
        return f"{dt.year:04d}-{dt.month:02d}"

    cur_month = _current_usage_month()
    if ws.get("usage_month") != cur_month:
        ws["usage_month"] = cur_month
        ws["pages_used"] = 0
        ws["llm_tokens_used"] = 0
        ws["updated_at"] = now
        for i, w in enumerate(workspaces):
            if isinstance(w, dict) and w.get("id") == ws.get("id"):
                workspaces[i] = ws
                break
        _save("workspaces.json", workspaces)

    # Create job
    job_id = "fc_job_" + uuid.uuid4().hex
    inp = {
        "url": url,
        "max_pages": max_pages,
        "respect_robots_txt": respect_robots_txt if respect_robots_txt is not None else True,
        "output_format": "text"
    }
    job = {
        "id": job_id,
        "workspace_id": ws["id"],
        "api_key_id": api_key.get("id"),
        "tool": "firecrawl_generate_llmstxt",
        "status": "queued",
        "priority": priority if priority is not None else 0,
        "input": inp,
        "webhook_url": webhook_url,
        "webhook_secret": webhook_secret,
        "started_at": None,
        "finished_at": None,
        "error_code": None,
        "error_message": None,
        "result_summary": None,
        "pages_fetched": 0,
        "llm_tokens_used": 0,
        "created_at": now,
        "updated_at": now
    }
    jobs.append(job)

    # Update api key last_used_at
    api_key["last_used_at"] = now
    api_key["updated_at"] = now
    for i, k in enumerate(api_keys):
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            api_keys[i] = api_key
            break

    # Find or create page artifact in same workspace
    page = next((p for p in pages if isinstance(p, dict) and p.get("workspace_id") == ws["id"] and p.get("url") == url and p.get("status") != "deleted"), None)
    if not page:
        page_id = "fc_page_" + uuid.uuid4().hex
        page = {
            "id": page_id,
            "workspace_id": ws["id"],
            "source_job_id": job_id,
            "url": url,
            "fetched_url": url,
            "status": "stored",
            "content_type": None,
            "language": None,
            "title": None,
            "html": None,
            "text": None,
            "markdown": None,
            "metadata": {"generated": True, "purpose": "llms_txt"},
            "extracted_data": None,
            "llms_txt": None,
            "content_sha256": None,
            "created_at": now,
            "updated_at": now
        }
        pages.append(page)

    # Estimate usage: 1 page, some tokens
    est_pages = 1
    est_tokens = 600  # generation tokens

    would_pages = int(ws.get("pages_used", 0)) + est_pages
    would_tokens = int(ws.get("llm_tokens_used", 0)) + est_tokens
    if would_pages > int(ws.get("monthly_page_limit", 0)) or would_tokens > int(ws.get("monthly_llm_token_limit", 0)):
        job["status"] = "failed"
        job["started_at"] = now
        job["finished_at"] = now
        job["error_code"] = "quota_exceeded"
        job["error_message"] = "Monthly quota exceeded"
        job["result_summary"] = {"quota": {"pages_would_be": would_pages, "tokens_would_be": would_tokens}}
        job["updated_at"] = now
        if webhook_url:
            rs = job.get("result_summary") or {}
            rs["webhook"] = {"attempted_at": now, "status_code": 0, "error": "delivery_not_available_offline"}
            job["result_summary"] = rs
        for i, j in enumerate(jobs):
            if isinstance(j, dict) and j.get("id") == job_id:
                jobs[i] = job
                break
        _save("jobs.json", jobs)
        _save("pages.json", pages)
        _save("api_keys.json", api_keys)
        _log("error", api_key_id=api_key.get("id"), workspace_id_log=ws.get("id"), error_code="QUOTA_EXCEEDED")
        return _err("QUOTA_EXCEEDED", "Monthly quota exceeded", job_id=job_id)

    # Synchronous completion: write llms_txt into page
    parsed = urllib.parse.urlparse(url)
    base = f"{parsed.scheme}://{parsed.netloc}"
    llms_txt = (
        f"# LLMs.txt\n\n"
        f"site: {base}\n"
        f"generated_for: {url}\n"
        f"respect_robots_txt: {inp['respect_robots_txt']}\n"
        f"max_pages_inspected: {max_pages if max_pages is not None else ''}\n\n"
        f"## Guidance\n"
        f"- Prefer official pages and documentation.\n"
        f"- Cite sources with canonical URLs.\n"
        f"- Avoid sensitive or personal data.\n"
    )
    page["llms_txt"] = llms_txt
    page["updated_at"] = now
    page["source_job_id"] = page.get("source_job_id") or job_id

    # Persist page
    for i, p in enumerate(pages):
        if isinstance(p, dict) and p.get("id") == page.get("id"):
            pages[i] = page
            break

    # Mark job succeeded
    job["status"] = "succeeded"
    job["started_at"] = now
    job["finished_at"] = now
    job["pages_fetched"] = est_pages
    job["llm_tokens_used"] = est_tokens
    job["result_summary"] = {"page_id": page["id"], "url": url, "bytes": len(llms_txt)}
    if webhook_url:
        rs = job.get("result_summary") or {}
        rs["webhook"] = {"attempted_at": now, "status_code": 0, "error": "delivery_not_available_offline"}
        job["result_summary"] = rs
    job["updated_at"] = now
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("id") == job_id:
            jobs[i] = job
            break

    _save("jobs.json", jobs)
    _save("pages.json", pages)
    _save("api_keys.json", api_keys)

    # Quota accounting
    ws["pages_used"] = int(ws.get("pages_used", 0)) + est_pages
    ws["llm_tokens_used"] = int(ws.get("llm_tokens_used", 0)) + est_tokens
    ws["updated_at"] = now
    for i, w in enumerate(workspaces):
        if isinstance(w, dict) and w.get("id") == ws.get("id"):
            workspaces[i] = ws
            break
    _save("workspaces.json", workspaces)

    _log("success", api_key_id=api_key.get("id"), workspace_id_log=ws.get("id"))
    return {"job": job, "page": {"id": page["id"], "url": page["url"], "llms_txt": page["llms_txt"]}}

def firecrawl_check_job_status(id, includeItems=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0122000" if __import__("os").path.isdir("./environment_mix/0122000") else "/app/database")
    _t0 = time.time()

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_month_bucket(ws):
        now_m = datetime.datetime.utcnow().strftime("%Y-%m")
        if isinstance(ws, dict) and ws.get("usage_month") != now_m:
            ws["usage_month"] = now_m
            ws["pages_used"] = 0
            ws["llm_tokens_used"] = 0
            ws["updated_at"] = _now_iso()
        return ws

    def _log(endpoint, api_key_id, workspace_id, status_txt, error_code=None):
        fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
                "timestamp": _now_iso(),
                "status": status_txt,
                "error_code": error_code,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save(fname, logs)

    def _resolve_auth_for_job(job):
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        ws_id = job.get("workspace_id") if isinstance(job, dict) else None
        ws = None
        if isinstance(workspaces, list) and isinstance(ws_id, str):
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
        if not ws or ws.get("status") != "active":
            return None, None, api_keys, workspaces
        if not isinstance(api_keys, list):
            api_keys = []
        key = next((k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == ws_id and k.get("status") == "active"), None)
        if not key:
            return None, ws, api_keys, workspaces
        return key, ws, api_keys, workspaces

    if not isinstance(id, str) or not id.strip():
        _log("firecrawl_check_job_status", None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if includeItems is not None and not isinstance(includeItems, bool):
        _log("firecrawl_check_job_status", None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "includeItems must be a boolean")

    jobs = _load("jobs.json")
    if not isinstance(jobs, list):
        jobs = []
    job = next((j for j in jobs if isinstance(j, dict) and j.get("id") == id), None)

    # Compatibility: if passed a workspace id, resolve to most recent job in that workspace
    if job is None and id.startswith("fc_wsp_"):
        cand = [j for j in jobs if isinstance(j, dict) and j.get("workspace_id") == id]
        cand.sort(key=lambda x: x.get("created_at") or "", reverse=True)
        job = cand[0] if cand else None

    if not job:
        _log("firecrawl_check_job_status", None, None, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "UNKNOWN_JOB: job id does not exist")

    key, ws, api_keys, workspaces = _resolve_auth_for_job(job)
    if not key or not ws:
        _log("firecrawl_check_job_status", None, job.get("workspace_id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "FORBIDDEN: API key is not active or workspace is not active")

    now = _now_iso()
    key["last_used_at"] = now
    key["updated_at"] = key.get("updated_at") or now
    ws = _ensure_month_bucket(ws)
    _save("api_keys.json", api_keys)
    _save("workspaces.json", workspaces)

    out = {
        "job": {
            "id": job.get("id"),
            "workspace_id": job.get("workspace_id"),
            "api_key_id": job.get("api_key_id"),
            "tool": job.get("tool"),
            "status": job.get("status"),
            "priority": job.get("priority"),
            "input": job.get("input"),
            "webhook_url": job.get("webhook_url"),
            "started_at": job.get("started_at"),
            "finished_at": job.get("finished_at"),
            "error_code": job.get("error_code"),
            "error_message": job.get("error_message"),
            "result_summary": job.get("result_summary"),
            "pages_fetched": job.get("pages_fetched"),
            "llm_tokens_used": job.get("llm_tokens_used"),
            "created_at": job.get("created_at"),
            "updated_at": job.get("updated_at"),
        }
    }

    if includeItems:
        job_items = _load("job_items.json")
        if not isinstance(job_items, list):
            job_items = []
        items = [it for it in job_items if isinstance(it, dict) and it.get("job_id") == job.get("id")]
        by_status = {}
        by_kind = {}
        for it in items:
            st = it.get("status")
            if isinstance(st, str):
                by_status[st] = by_status.get(st, 0) + 1
            kd = it.get("kind")
            if isinstance(kd, str):
                by_kind[kd] = by_kind.get(kd, 0) + 1
        out["items_summary"] = {"total": len(items), "by_status": by_status, "by_kind": by_kind}

    _log("firecrawl_check_job_status", key.get("id"), ws.get("id"), "ok", None)
    return out

def firecrawl_cancel_job(id, reason=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0122000" if __import__("os").path.isdir("./environment_mix/0122000") else "/app/database")
    _t0 = time.time()

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_month_bucket(ws):
        now_m = datetime.datetime.utcnow().strftime("%Y-%m")
        if isinstance(ws, dict) and ws.get("usage_month") != now_m:
            ws["usage_month"] = now_m
            ws["pages_used"] = 0
            ws["llm_tokens_used"] = 0
            ws["updated_at"] = _now_iso()
        return ws

    def _log(endpoint, api_key_id, workspace_id, status_txt, error_code=None):
        fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
                "timestamp": _now_iso(),
                "status": status_txt,
                "error_code": error_code,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save(fname, logs)

    def _resolve_auth_for_job(job):
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        ws_id = job.get("workspace_id") if isinstance(job, dict) else None
        ws = None
        if isinstance(workspaces, list) and isinstance(ws_id, str):
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == ws_id), None)
        if not ws or ws.get("status") != "active":
            return None, None, api_keys, workspaces
        if not isinstance(api_keys, list):
            api_keys = []
        key = next((k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == ws_id and k.get("status") == "active"), None)
        if not key:
            return None, ws, api_keys, workspaces
        return key, ws, api_keys, workspaces

    if not isinstance(id, str) or not id.strip():
        _log("firecrawl_cancel_job", None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if reason is not None and not isinstance(reason, str):
        _log("firecrawl_cancel_job", None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "reason must be a string")

    jobs = _load("jobs.json")
    if not isinstance(jobs, list):
        jobs = []

    job_idx = None
    job = None
    for i, j in enumerate(jobs):
        if isinstance(j, dict) and j.get("id") == id:
            job_idx = i
            job = j
            break

    # Compatibility: callers may pass a workspace id; cancel the most recent cancellable job for that workspace
    if job is None and id.startswith("fc_wsp_"):
        cand = [(i, j) for i, j in enumerate(jobs) if isinstance(j, dict) and j.get("workspace_id") == id and j.get("status") in ("queued", "running")]
        cand.sort(key=lambda ij: (ij[1].get("created_at") or ""), reverse=True)
        if cand:
            job_idx, job = cand[0]

    if not job:
        _log("firecrawl_cancel_job", None, None, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "UNKNOWN_JOB: job id does not exist")

    key, ws, api_keys, workspaces = _resolve_auth_for_job(job)
    if not key or not ws:
        _log("firecrawl_cancel_job", None, job.get("workspace_id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "FORBIDDEN: API key is not active or workspace is not active")

    # enforce lifecycle transitions
    terminal = {"succeeded", "failed", "cancelled", "expired"}
    if job.get("status") in terminal:
        _log("firecrawl_cancel_job", key.get("id"), ws.get("id"), "error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "INVALID_STATE: cannot cancel a terminal job", status=job.get("status"))

    if job.get("status") not in ("queued", "running"):
        _log("firecrawl_cancel_job", key.get("id"), ws.get("id"), "error", "INVALID_TRANSITION")
        return _err("INVALID_TRANSITION", "INVALID_STATE: only queued or running jobs can be cancelled", status=job.get("status"))

    now = _now_iso()
    job["status"] = "cancelled"
    job["updated_at"] = now
    if not job.get("finished_at"):
        job["finished_at"] = now

    rs = job.get("result_summary")
    if not isinstance(rs, dict):
        rs = {}
    if reason:
        rs["cancel_reason"] = reason
    rs.setdefault("cancelled_at", now)
    job["result_summary"] = rs

    jobs[job_idx] = job
    _save("jobs.json", jobs)

    # update last_used_at & persist
    key["last_used_at"] = now
    key["updated_at"] = key.get("updated_at") or now
    ws = _ensure_month_bucket(ws)
    _save("api_keys.json", api_keys)
    _save("workspaces.json", workspaces)

    _log("firecrawl_cancel_job", key.get("id"), ws.get("id"), "ok", None)
    return {"job": job}

def firecrawl_list_jobs(tool=None, status=None, limit=None, cursor=None, createdAfter=None, createdBefore=None, **_extra):
    import json, os, datetime, time, re, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0122000" if __import__("os").path.isdir("./environment_mix/0122000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    # ---- helpers ----
    def _parse_iso(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s.strip():
            return "BAD"
        ss = s.strip()
        # Accept Z
        if ss.endswith("Z"):
            ss = ss[:-1] + "+00:00"
        try:
            dt = datetime.datetime.fromisoformat(ss)
        except ValueError:
            return "BAD"
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=datetime.timezone.utc)
        return dt.astimezone(datetime.timezone.utc)

    def _b64u_enc(obj):
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        return base64.urlsafe_b64encode(raw).decode("ascii").rstrip("=")

    def _b64u_dec(s):
        if s is None:
            return None
        if not isinstance(s, str) or not s:
            return "BAD"
        pad = "=" * (-len(s) % 4)
        try:
            raw = base64.urlsafe_b64decode((s + pad).encode("ascii"))
            return json.loads(raw.decode("utf-8"))
        except Exception:
            return "BAD"

    def _month_bucket(dt):
        return dt.strftime("%Y-%m")

    def _maybe_reset_monthly_usage(ws_row):
        # reset usage if usage_month differs from current UTC month
        cur = _month_bucket(now)
        if ws_row.get("usage_month") != cur:
            ws_row["usage_month"] = cur
            ws_row["pages_used"] = 0
            ws_row["llm_tokens_used"] = 0
            ws_row["updated_at"] = now_iso
            return True
        return False

    def _select_auth_context():
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")

        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
        # pick an active key whose workspace is active
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            ws = ws_by_id.get(k.get("workspace_id"))
            if not ws or ws.get("status") != "active":
                continue
            return k, ws, api_keys, workspaces
        return None, None, api_keys, workspaces

    def _log_request(endpoint, api_key_id, workspace_id, status_code, error_code=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(now.timestamp()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": now_iso,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    # ---- validate inputs ----
    allowed_tools = {
        "firecrawl_scrape", "firecrawl_batch_scrape", "firecrawl_crawl", "firecrawl_map",
        "firecrawl_search", "firecrawl_extract", "firecrawl_deep_research", "firecrawl_generate_llmstxt"
    }
    allowed_status = {"queued", "running", "succeeded", "failed", "cancelled", "expired"}

    if tool is not None:
        if not isinstance(tool, str) or tool not in allowed_tools:
            _log_request("firecrawl_list_jobs", None, None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'tool' filter.", allowed=list(sorted(allowed_tools)))
    if status is not None:
        if not isinstance(status, str) or status not in allowed_status:
            _log_request("firecrawl_list_jobs", None, None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'status' filter.", allowed=list(sorted(allowed_status)))
    if limit is None:
        limit_i = 20
    else:
        if not isinstance(limit, int):
            _log_request("firecrawl_list_jobs", None, None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'limit'; must be integer 1-100.")
        if limit < 1 or limit > 100:
            _log_request("firecrawl_list_jobs", None, None, 400, "VALIDATION_ERROR")
            return _err("VALIDATION_ERROR", "Invalid 'limit'; must be in range 1-100.")
        limit_i = limit

    ca = _parse_iso(createdAfter)
    if ca == "BAD":
        _log_request("firecrawl_list_jobs", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'createdAfter'; must be ISO-8601 timestamp.")
    cb = _parse_iso(createdBefore)
    if cb == "BAD":
        _log_request("firecrawl_list_jobs", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'createdBefore'; must be ISO-8601 timestamp.")
    if ca and cb and cb < ca:
        _log_request("firecrawl_list_jobs", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "'createdBefore' must be >= 'createdAfter'.")

    cur = _b64u_dec(cursor)
    if cur == "BAD":
        _log_request("firecrawl_list_jobs", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'cursor'.")

    # ---- auth ----
    api_key, ws, api_keys_all, workspaces_all = _select_auth_context()
    if not api_key or not ws:
        _log_request("firecrawl_list_jobs", None, None, 403, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "FORBIDDEN: API key is missing/revoked or workspace is not active.")

    # monthly usage bucket maintenance
    ws_changed = _maybe_reset_monthly_usage(ws)
    if ws_changed:
        # persist workspace update
        for i, w in enumerate(workspaces_all):
            if isinstance(w, dict) and w.get("id") == ws.get("id"):
                workspaces_all[i] = ws
                break
        _save("workspaces.json", workspaces_all)

    # last_used_at update on successful auth
    api_key["last_used_at"] = now_iso
    api_key["updated_at"] = api_key.get("updated_at") or now_iso
    for i, k in enumerate(api_keys_all):
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            api_keys_all[i] = api_key
            break
    _save("api_keys.json", api_keys_all)

    # ---- query ----
    jobs = _load("jobs.json")
    rows = [j for j in jobs if isinstance(j, dict) and j.get("workspace_id") == ws.get("id")]

    if tool is not None:
        rows = [j for j in rows if j.get("tool") == tool]
    if status is not None:
        rows = [j for j in rows if j.get("status") == status]

    def _job_created_dt(j):
        s = j.get("created_at")
        dt = _parse_iso(s) if isinstance(s, str) else None
        if dt in (None, "BAD"):
            return datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc)
        return dt

    if ca:
        rows = [j for j in rows if _job_created_dt(j) > ca]
    if cb:
        rows = [j for j in rows if _job_created_dt(j) < cb]

    # order by created_at desc, stable tie-breaker id desc
    rows.sort(key=lambda j: (_job_created_dt(j), str(j.get("id", ""))), reverse=True)

    start = 0
    if isinstance(cur, dict):
        # cursor supports either index or seek by created_at+id
        if "offset" in cur:
            off = cur.get("offset")
            if isinstance(off, int) and off >= 0:
                start = off
        elif "after" in cur:
            after = cur.get("after")
            if isinstance(after, dict):
                a_ts = _parse_iso(after.get("created_at"))
                a_id = after.get("id")
                if a_ts != "BAD" and isinstance(a_id, str):
                    # find first row strictly older than (a_ts,a_id) in our desc ordering
                    def _cmp_key(j):
                        return (_job_created_dt(j), str(j.get("id", "")))
                    target = (a_ts if a_ts else datetime.datetime(1970, 1, 1, tzinfo=datetime.timezone.utc), a_id)
                    idx = 0
                    for j in rows:
                        if _cmp_key(j) < target:
                            break
                        idx += 1
                    start = idx

    page = rows[start:start + limit_i]
    has_more = start + limit_i < len(rows)
    next_cursor = None
    if has_more and page:
        last = page[-1]
        next_cursor = _b64u_enc({"after": {"created_at": last.get("created_at"), "id": last.get("id")}})

    # response shaping: return job records as stored
    resp = {
        "success": True,
        "jobs": page,
        "limit": limit_i,
        "total": len(rows),
        "has_more": has_more,
        "nextCursor": next_cursor
    }

    _log_request("firecrawl_list_jobs", api_key.get("id"), ws.get("id"), 200)
    return resp

