    return resp

def firecrawl_get_page(id, includeContent=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0122000" if __import__("os").path.isdir("./environment_mix/0122000") else "/app/database")
    _t0 = time.time()

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_month_bucket(ws):
        now_m = datetime.datetime.utcnow().strftime("%Y-%m")
        if isinstance(ws, dict) and ws.get("usage_month") != now_m:
            ws["usage_month"] = now_m
            ws["pages_used"] = 0
            ws["llm_tokens_used"] = 0
            ws["updated_at"] = _now_iso()
        return ws

    def _log(endpoint, api_key_id, workspace_id, status_txt, error_code=None):
        fname = "request_logs.json"
        logs = _load(fname)
        if not isinstance(logs, list):
            logs = []
        logs.append(
            {
                "id": f"req_{int(time.time()*1000)}_{os.getpid()}_{len(logs)+1}",
                "endpoint": endpoint,
                "timestamp": _now_iso(),
                "status": status_txt,
                "error_code": error_code,
                "api_key_id": api_key_id,
                "workspace_id": workspace_id,
                "latency_ms": int((time.time() - _t0) * 1000),
            }
        )
        _save(fname, logs)

    def _resolve_auth_for_workspace(workspace_id):
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        ws = None
        if isinstance(workspaces, list):
            ws = next((w for w in workspaces if isinstance(w, dict) and w.get("id") == workspace_id), None)
        if not ws or ws.get("status") != "active":
            return None, ws, api_keys, workspaces
        if not isinstance(api_keys, list):
            api_keys = []
        key = next((k for k in api_keys if isinstance(k, dict) and k.get("workspace_id") == workspace_id and k.get("status") == "active"), None)
        if not key:
            return None, ws, api_keys, workspaces
        return key, ws, api_keys, workspaces

    if not isinstance(id, str) or not id.strip():
        _log("firecrawl_get_page", None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "id must be a non-empty string")
    if includeContent is not None and not isinstance(includeContent, bool):
        _log("firecrawl_get_page", None, None, "error", "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "includeContent must be a boolean")

    pages = _load("pages.json")
    if not isinstance(pages, list):
        pages = []
    page = next((p for p in pages if isinstance(p, dict) and p.get("id") == id), None)

    # Compatibility: if passed a workspace id, return the most recent stored page for that workspace
    if page is None and id.startswith("fc_wsp_"):
        cand = [p for p in pages if isinstance(p, dict) and p.get("workspace_id") == id]
        cand.sort(key=lambda x: x.get("created_at") or "", reverse=True)
        page = cand[0] if cand else None

    if not page:
        _log("firecrawl_get_page", None, None, "error", "NOT_FOUND")
        return _err("NOT_FOUND", "UNKNOWN_PAGE: page id does not exist")

    key, ws, api_keys, workspaces = _resolve_auth_for_workspace(page.get("workspace_id"))
    if not key or not ws:
        _log("firecrawl_get_page", None, page.get("workspace_id"), "error", "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "FORBIDDEN: API key is not active or workspace is not active")

    now = _now_iso()
    key["last_used_at"] = now
    key["updated_at"] = key.get("updated_at") or now
    ws = _ensure_month_bucket(ws)
    _save("api_keys.json", api_keys)
    _save("workspaces.json", workspaces)

    # response shaping: metadata always, content fields optional
    out_page = {
        "id": page.get("id"),
        "workspace_id": page.get("workspace_id"),
        "source_job_id": page.get("source_job_id"),
        "url": page.get("url"),
        "fetched_url": page.get("fetched_url"),
        "status": page.get("status"),
        "content_type": page.get("content_type"),
        "language": page.get("language"),
        "title": page.get("title"),
        "content_sha256": page.get("content_sha256"),
        "created_at": page.get("created_at"),
        "updated_at": page.get("updated_at"),
    }
    if includeContent:
        out_page.update(
            {
                "html": page.get("html"),
                "text": page.get("text"),
                "markdown": page.get("markdown"),
                "metadata": page.get("metadata"),
                "extracted_data": page.get("extracted_data"),
                "llms_txt": page.get("llms_txt"),
            }
        )

    _log("firecrawl_get_page", key.get("id"), ws.get("id"), "ok", None)
    return {"page": out_page}

def firecrawl_whoami(includeApiKey=None, includeWorkspace=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0122000" if __import__("os").path.isdir("./environment_mix/0122000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    t0 = time.time()
    now = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now.isoformat()

    def _month_bucket(dt):
        return dt.strftime("%Y-%m")

    def _maybe_reset_monthly_usage(ws_row):
        cur = _month_bucket(now)
        if ws_row.get("usage_month") != cur:
            ws_row["usage_month"] = cur
            ws_row["pages_used"] = 0
            ws_row["llm_tokens_used"] = 0
            ws_row["updated_at"] = now_iso
            return True
        return False

    def _select_auth_context():
        api_keys = _load("api_keys.json")
        workspaces = _load("workspaces.json")
        ws_by_id = {w.get("id"): w for w in workspaces if isinstance(w, dict)}
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            ws = ws_by_id.get(k.get("workspace_id"))
            if not ws or ws.get("status") != "active":
                continue
            return k, ws, api_keys, workspaces
        return None, None, api_keys, workspaces

    def _log_request(endpoint, api_key_id, workspace_id, status_code, error_code=None, extra=None):
        logs = _load("request_logs.json")
        if not isinstance(logs, list):
            logs = []
        row = {
            "id": f"req_{int(now.timestamp()*1000)}_{os.getpid()}_{len(logs)+1}",
            "ts": now_iso,
            "endpoint": endpoint,
            "api_key_id": api_key_id,
            "workspace_id": workspace_id,
            "status": status_code,
            "error_code": error_code,
            "latency_ms": int((time.time() - t0) * 1000),
        }
        if extra is not None:
            row["meta"] = extra
        logs.append(row)
        _save("request_logs.json", logs)

    # ---- validate ----
    if includeApiKey is not None and not isinstance(includeApiKey, bool):
        _log_request("firecrawl_whoami", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'includeApiKey'; must be boolean.")
    if includeWorkspace is not None and not isinstance(includeWorkspace, bool):
        _log_request("firecrawl_whoami", None, None, 400, "VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Invalid 'includeWorkspace'; must be boolean.")

    inc_key = True if includeApiKey is None else bool(includeApiKey)
    inc_ws = True if includeWorkspace is None else bool(includeWorkspace)

    # ---- auth ----
    api_key, ws, api_keys_all, workspaces_all = _select_auth_context()
    if not api_key or not ws:
        _log_request("firecrawl_whoami", None, None, 403, "UNAUTHORIZED")
        return _err("UNAUTHORIZED", "FORBIDDEN: API key is missing/revoked or workspace is not active.")

    # keep monthly bucket consistent
    ws_changed = _maybe_reset_monthly_usage(ws)
    if ws_changed:
        for i, w in enumerate(workspaces_all):
            if isinstance(w, dict) and w.get("id") == ws.get("id"):
                workspaces_all[i] = ws
                break
        _save("workspaces.json", workspaces_all)

    # update last_used_at on successful auth
    api_key["last_used_at"] = now_iso
    api_key["updated_at"] = api_key.get("updated_at") or now_iso
    for i, k in enumerate(api_keys_all):
        if isinstance(k, dict) and k.get("id") == api_key.get("id"):
            api_keys_all[i] = api_key
            break
    _save("api_keys.json", api_keys_all)

    # ---- response ----
    scopes = ["jobs:read", "pages:read", "scrape:write", "crawl:write", "search:write", "extract:write"]

    out = {"success": True, "scopes": scopes}

    if inc_key:
        out["api_key"] = {
            "id": api_key.get("id"),
            "name": api_key.get("name"),
            "key_prefix": api_key.get("key_prefix"),
            "status": api_key.get("status"),
            "last_used_at": api_key.get("last_used_at"),
            "created_at": api_key.get("created_at"),
            "updated_at": api_key.get("updated_at"),
        }
    if inc_ws:
        out["workspace"] = {
            "id": ws.get("id"),
            "name": ws.get("name"),
            "plan": ws.get("plan"),
            "status": ws.get("status"),
            "monthly_page_limit": ws.get("monthly_page_limit"),
            "monthly_llm_token_limit": ws.get("monthly_llm_token_limit"),
            "usage_month": ws.get("usage_month"),
            "pages_used": ws.get("pages_used"),
            "llm_tokens_used": ws.get("llm_tokens_used"),
            "created_at": ws.get("created_at"),
            "updated_at": ws.get("updated_at"),
        }

    _log_request("firecrawl_whoami", api_key.get("id"), ws.get("id"), 200)
    return out
